def save_raw_u16_tiff(image_raw, path: Path) -> None:
    """Save one untouched PCO uint16 frame as an uncompressed 16-bit TIFF."""
    if np is None or Image is None:
        raise RuntimeError("Saving a 16-bit image requires numpy and Pillow")
    array = np.asarray(image_raw)
    if array.ndim != 2:
        raise RuntimeError(f"The raw camera frame must be a 2-D grayscale image; current shape={array.shape}")
    if array.dtype != np.uint16:
        raise RuntimeError(
            f"Refusing to change the raw bit depth: camera returned {array.dtype}, expected uint16"
        )
    destination = Path(path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    Image.fromarray(array).save(destination, format="TIFF", compression="raw")


def save_processed_f32_tiff(image_processed, path: Path) -> None:
    """Save signed processed difference values without applying display CLim."""
    if np is None or Image is None:
        raise RuntimeError("Saving the processed image requires numpy and Pillow")
    array = np.asarray(image_processed, dtype=np.float32)
    if array.ndim != 2:
        raise RuntimeError(f"The processed image must be a 2-D grayscale image; current shape={array.shape}")
    if not np.all(np.isfinite(array)):
        raise RuntimeError("The processed image contains NaN or infinite values; save refused")
    destination = Path(path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    # Pillow stores a float32 array as TIFF mode F, preserving negative values.
    Image.fromarray(array).save(destination, format="TIFF", compression="raw")


def cidwm_sign_sequence(count, signs) -> tuple[int, ...]:
    """The CIDWM pulse sign scan's signs, +1 or -1 per pulse: ``signs`` as
    "+" and "-" ("−" too; spaces and commas ignored), repeated until there
    are ``count`` of them ("+-" alternates, "++--" goes in pairs)."""
    try:
        value = float(count)
    except (TypeError, ValueError) as error:
        raise ValueError("Pulses must be a whole number") from error
    if not (math.isfinite(value) and value.is_integer() and 1 <= value <= CIDWM_SCAN_MAX_PULSES):
        raise ValueError(f"Pulses must be a whole number from 1 to {CIDWM_SCAN_MAX_PULSES}")
    pattern = []
    for character in str(signs):
        if character == "+":
            pattern.append(1)
        elif character in "-−":
            pattern.append(-1)
        elif not (character.isspace() or character == ","):
            raise ValueError(f"Signs may only hold + and -, not {character!r}")
    if not pattern:
        raise ValueError("Signs must hold at least one + or -")
    return tuple(pattern[index % len(pattern)] for index in range(int(value)))


def save_display_u8_png(image_display, path: Path) -> None:
    """Save the marker-free 8-bit image currently mapped into Camera Live."""
    if np is None or Image is None:
        raise RuntimeError("Saving the currently displayed image requires numpy and Pillow")
    array = np.asarray(image_display)
    if array.ndim != 2 or array.dtype != np.uint8:
        raise RuntimeError(
            f"Unexpected format of the currently displayed image: dtype={array.dtype}, shape={array.shape}"
        )
    destination = Path(path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    Image.fromarray(array, mode="L").save(destination, format="PNG")


