def orient_camera_image(image):
    """Return a contiguous PCO image rotated 90 degrees counterclockwise."""
    array = np.asarray(image)
    if array.ndim != 2:
        raise ValueError(
            f"The PCO camera frame must be a 2-D grayscale image; current shape={array.shape}"
        )
    return np.rot90(
        array,
        k=CAMERA_ROTATION_QUARTER_TURNS_CCW,
    ).copy()


