    def _enforce_english_input_mode(self, event=None) -> None:
        """Reapply English after Windows restores a per-window IME state."""
        target = getattr(event, "widget", self.root)
        try:
            self.root.after_idle(
                lambda selected=target: force_english_input_mode(selected)
            )
        except tk.TclError:
            pass

    def _ui_px(
        self,
        value: int | float,
        minimum: int = 1,
        *,
        canvas: bool = False,
    ) -> int:
        """Scale a requested pixel size for the active logical display."""
        scale = self.canvas_scale if canvas else self.ui_scale
        return max(int(minimum), int(round(float(value) * scale)))

    def _arrange_pair_by_width(
        self, container, left, right, *, gap: int = 4, stack_gap: int | None = None
    ) -> None:
        """Place two sections side by side when both fit, otherwise stack them.

        On a wide screen the program opens the control window at about 43 % of
        the screen width (826 px on a 1920 display).  There the 4886 output and
        the connection list do not fit on one row, and a fixed side-by-side
        layout would clip the right-hand one.  Re-evaluated on every resize.
        """
        def arrange(_event=None) -> None:
            try:
                # A LabelFrame's padding and border are not usable width.
                # ttk returns padding as a tuple such as (7,) or a Tcl list.
                raw = container.cget("padding") if "padding" in container.keys() else ()
                padding = [int(float(str(v))) for v in container.tk.splitlist(raw)] or [0]
                inset = padding[0] + (padding[2] if len(padding) > 2 else padding[0])
                if container.winfo_class() == "TLabelframe":
                    inset += 4
                available = container.winfo_width() - inset
                needed = (
                    self._pair_natural_width(left)
                    + self._pair_natural_width(right)
                    + gap
                )
            except (tk.TclError, ValueError):
                return
            # What this container needs for side by side, for any pair that
            # contains it (see _pair_natural_width).
            container._pair_wide_need = needed + inset
            if available <= 1:
                return  # not laid out yet; the first <Configure> decides
            wide = available >= needed
            if getattr(container, "_pair_side_by_side", None) is wide:
                return
            # A pair whose width follows its own layout (its column sized by
            # its content) flips at every <Configure> and the window never
            # finishes drawing: 2026-10-12, the CIDWM difference display's
            # mode row hung the program at start-up.  After PAIR_FLIP_LIMIT
            # flips within a second at one window width it stays stacked,
            # the layout that never clips, until the window is resized.
            try:
                window_width = container.winfo_toplevel().winfo_width()
            except (tk.TclError, AttributeError):
                window_width = None
            now = time.monotonic()
            guard = getattr(container, "_pair_flip_guard", None)
            if guard is None or guard["window"] != window_width:
                guard = {"window": window_width, "since": now, "flips": 0, "held": False}
                container._pair_flip_guard = guard
            if guard["held"]:
                return  # stacked until the window is resized
            if now - guard["since"] > 1.0:
                guard["since"], guard["flips"] = now, 0
            guard["flips"] += 1
            if guard["flips"] > PAIR_FLIP_LIMIT:
                guard["held"] = True
                if getattr(container, "_pair_side_by_side", None) is False:
                    return
                wide = False
            container._pair_side_by_side = wide
            if wide:
                left.grid_configure(row=0, column=0, columnspan=1, padx=(0, gap), pady=0)
                right.grid_configure(row=0, column=1, columnspan=1, padx=0, pady=0)
            else:
                left.grid_configure(
                    row=0, column=0, columnspan=2, padx=0,
                    pady=(0, gap if stack_gap is None else stack_gap),
                )
                right.grid_configure(row=1, column=0, columnspan=2, padx=0, pady=0)

        container.bind("<Configure>", arrange, add="+")
        arrange()

    @staticmethod
    def _pair_natural_width(section) -> int:
        """Width a section requests with every pair inside it side by side.

        A section that holds its own pair requests less while that pair is
        stacked.  Judged by its current
        request, both "outer side, inner stacked" and "outer stacked, inner
        side" were stable at the same width, so the layout depended on how
        the window had been resized.  Judging by the side-by-side width makes
        the outer pair wait until the inner one fits side by side too.
        """
        extra = 0
        pending = list(section.winfo_children())
        while pending:
            child = pending.pop()
            need = getattr(child, "_pair_wide_need", None)
            if need is not None and getattr(child, "_pair_side_by_side", None) is False:
                extra = max(extra, int(need) - child.winfo_reqwidth())
            pending.extend(child.winfo_children())
        return section.winfo_reqwidth() + max(0, extra)

    def _keep_pair_left_room(self, container, left, right, *, gap: int) -> None:
        """While ``container``'s pair is side by side, its left column is at
        least as wide as ``left`` needs with its own inner pair side by side
        (RT-E's keep_settings_room).  Otherwise the left box is sized by its
        own request, which changes with its inner pair's layout: the shape
        that hung CIDWM at start-up on 2026-10-12.  Up to 4 px of slack, while
        the right box still gets its own width; the right box takes the rest.
        Call after _arrange_pair_by_width(container, left, right, gap=gap)."""
        def keep(_event=None) -> None:
            try:
                room = 0
                if getattr(container, "_pair_side_by_side", False) is True:
                    room = self._pair_natural_width(left) + gap
                    room = max(room, min(room + 4, container.winfo_width() - self._pair_natural_width(right)))
                container.columnconfigure(0, minsize=room)
            except tk.TclError:
                pass  # the window is closing

        container.bind("<Configure>", keep, add="+")

    def build_ui(self) -> None:
        self.root.rowconfigure(0, weight=1)
        self.root.columnconfigure(0, weight=1)

        self._configure_ui_styles()
        notebook_pad = self._ui_px(3, 2)
        self.notebook = ttk.Notebook(
            self.root,
            padding=(notebook_pad, notebook_pad, notebook_pad, 0),
        )
        self.notebook.grid(row=0, column=0, sticky="nsew")
        self.led_tab = ttk.Frame(self.notebook)
        self.motor_tab = ttk.Frame(self.notebook)
        self.difference_tab = ttk.Frame(self.notebook)
        self.keithley_tab = ttk.Frame(self.notebook)
        self.k6221_tab = ttk.Frame(self.notebook)
        self.nonlocal_vi_tab = ttk.Frame(self.notebook)
        self.stfmr_tab = ttk.Frame(self.notebook)
        self.stfmr_lockin_tab = ttk.Frame(self.notebook)
        self.notebook.add(self.led_tab, text="MOKE light")
        self.notebook.add(self.motor_tab, text="MOKE motor")
        self.notebook.add(self.difference_tab, text="MOKE magnet")
        # The 6221 pulse page with MOKE imaging: current-induced domain-wall
        # motion (user, 2026-10-12; was "MOKE-6221", after MOKE-24).
        self.notebook.add(self.k6221_tab, text="CIDWM")
        self.notebook.add(self.keithley_tab, text="MOKE-24")
        # Gate-VI, |R| vs time (from MOKE-24) and the I-V sweep, one rack.
        self.notebook.add(self.nonlocal_vi_tab, text="Non-local")
        # The PPMS page is an independent PPMSPanel instance (own controllers,
        # scan state and Zurich MFLI); the main app keeps only inert PPMS
        # defaults so shared modules can still inspect them.
        self.ppms_panel_tab = ttk.Frame(self.notebook)
        self.notebook.add(self.ppms_panel_tab, text="PPMS")
        self.rte_panel_tab = ttk.Frame(self.notebook)
        self.notebook.add(self.rte_panel_tab, text="RT-E")
        self.notebook.add(self.stfmr_tab, text="FMR")
        self.notebook.add(self.stfmr_lockin_tab, text="STFMR")
        self.led_tab.rowconfigure(0, weight=1)
        self.led_tab.columnconfigure(0, weight=1)
        self.motor_tab.rowconfigure(0, weight=1)
        self.motor_tab.columnconfigure(0, weight=1)
        self.difference_tab.rowconfigure(0, weight=1)
        self.difference_tab.columnconfigure(0, weight=1)
        self.keithley_tab.rowconfigure(0, weight=1)
        self.keithley_tab.columnconfigure(0, weight=1)
        self.k6221_tab.rowconfigure(0, weight=1)
        self.k6221_tab.columnconfigure(0, weight=1)
        self.nonlocal_vi_tab.rowconfigure(0, weight=1)
        self.nonlocal_vi_tab.columnconfigure(0, weight=1)
        self.stfmr_tab.rowconfigure(0, weight=1)
        self.stfmr_tab.columnconfigure(0, weight=1)
        self.stfmr_lockin_tab.rowconfigure(0, weight=1)
        self.stfmr_lockin_tab.columnconfigure(0, weight=1)
        self.build_difference_ui()
        self.build_keithley_ui()
        self.build_k6221_ui()
        self.build_nonlocal_vi_ui()
        self.ppms_panel = PPMSPanel(self, self.ppms_panel_tab)
        self.rte_panel = RTEPanel(self, self.rte_panel_tab)
        self.build_stfmr_ui()
        self.build_stfmr_lockin_ui()

        outer = ttk.Frame(self.led_tab, padding=8)
        outer.grid(row=0, column=0, sticky="nsew")
        # The LED channels keep their natural width and the ROI graph beside
        # them takes the rest, so a wide window widens the graph instead of
        # opening a gap inside each channel row.
        outer.columnconfigure(0, weight=0)
        outer.columnconfigure(1, weight=1)
        # Keep the raw-ROI graph at its requested height.  A dedicated blank
        # row absorbs the extra height of the full-screen control window.
        outer.rowconfigure(4, weight=0)
        outer.rowconfigure(6, weight=0)
        outer.rowconfigure(7, weight=1)
