    def _set_stfmr_device_ui(self, key: str, connected: bool) -> None:
        self._set_connection_indicator(f"stfmr_{key}", connected)
        self.stfmr_device_connect_buttons[key].configure(
            state="disabled" if connected else "normal"
        )
        self.stfmr_device_disconnect_buttons[key].configure(
            state="normal" if connected else "disabled"
        )
        self.stfmr_device_resource_widgets[key].configure(
            state="disabled" if connected else "normal"
        )
        if key == "kepco":
            self.stfmr_apply_output_button.configure(
                state="normal" if connected else "disabled"
            )
            self.stfmr_read_output_button.configure(
                state="normal" if connected else "disabled"
            )
            self.stfmr_zero_output_button.configure(
                state="normal" if connected else "disabled"
            )
        elif key == "gauss":
            self.stfmr_read_gauss_button.configure(
                state="normal" if connected else "disabled"
            )
        if hasattr(self, "stfmr_fmr_start_button"):
            fmr_ready = all(
                self.stfmr_controllers[name].connected
                for name in ("kepco", "gauss", "vna")
            )
            self.stfmr_fmr_start_button.configure(
                state=(
                    "normal"
                    if fmr_ready
                    and not self.stfmr_fmr_running
                    and not self.stfmr_frequency_running
                    else "disabled"
                )
            )
            self.stfmr_frequency_start_button.configure(
                state=(
                    "normal"
                    if fmr_ready
                    and not self.stfmr_fmr_running
                    and not self.stfmr_frequency_running
                    else "disabled"
                )
            )

    def connect_stfmr_device(self, key: str) -> None:
        resource = self.stfmr_resource_vars[key].get().strip()
        self.stfmr_device_connect_buttons[key].configure(state="disabled")
        self.stfmr_device_resource_widgets[key].configure(state="disabled")
        self.stfmr_device_connection_vars[key].set("Connecting…")
        if key == "kepco":
            # NI-VISA on the STFMR computer identifies this legacy BIT 4886
            # reliably from the process main thread (as Scan_GPIB.py does),
            # while the same first transaction from a ThreadPoolExecutor can
            # time out and leave address 6 unresponsive to the next process.
            # Keep every operation on this session on Tk's main thread.
            try:
                identity = self.stfmr_controllers[key].connect(resource)
            except BaseException as error:
                self.stfmr_device_connection_vars[key].set("Connection failed")
                self._set_stfmr_device_ui(key, False)
                if not self.closing:
                    messagebox.showerror(
                        "STFMR instrument connection", str(error), parent=self.root
                    )
                return
            self.stfmr_device_connection_vars[key].set("Connected")
            self._set_stfmr_device_ui(key, True)
            self.stfmr_status_var.set("kepco connected")
            self.read_stfmr_kepco_once()
            return
        if key == "mfli":
            future = self.stfmr_executor.submit(
                self.stfmr_mfli_controller.connect_mfli, resource
            )
        else:
            future = self.stfmr_executor.submit(
                self.stfmr_controllers[key].connect, resource
            )

        def finished() -> None:
            try:
                identity = future.result()
            except BaseException as error:
                self.stfmr_device_connection_vars[key].set("Connection failed")
                self._set_stfmr_device_ui(key, False)
                if not self.closing:
                    messagebox.showerror("STFMR instrument connection", str(error), parent=self.root)
                return
            self.stfmr_device_connection_vars[key].set("Connected")
            self._set_stfmr_device_ui(key, True)
            self.stfmr_status_var.set(f"{key} connected")
            if key == "kepco":
                self.read_stfmr_kepco_once()
            elif key == "gauss":
                self.read_stfmr_gauss_once()

        future.add_done_callback(lambda _future: self.post_ui(finished))

    def disconnect_stfmr_device(self, key: str) -> None:
        self.stfmr_device_disconnect_buttons[key].configure(state="disabled")
        self.stfmr_device_connection_vars[key].set("Disconnecting…")
        if key == "kepco":
            try:
                self.stfmr_controllers[key].disconnect()
            except BaseException as error:
                if not self.closing:
                    messagebox.showerror(
                        "STFMR instrument disconnect", str(error), parent=self.root
                    )
            self.stfmr_device_connection_vars[key].set("Not connected")
            self._set_stfmr_device_ui(key, False)
            self.stfmr_kepco_mode_var.set("Mode: --")
            self.stfmr_kepco_current_var.set("I: -- A")
            self.stfmr_kepco_voltage_var.set("V: -- V")
            # A failed zero/OFF during disconnect leaves the output possibly on.
            self.stfmr_kepco_output_var.set(
                "OUTP: NOT CONFIRMED OFF"
                if self.stfmr_controllers["kepco"].output_owned
                else "OUTP: OFF"
            )
            return
        if key == "mfli":
            future = self.stfmr_executor.submit(
                self.stfmr_mfli_controller.disconnect_mfli
            )
        else:
            future = self.stfmr_executor.submit(
                self.stfmr_controllers[key].disconnect
            )

        def finished() -> None:
            try:
                future.result()
            except BaseException as error:
                if not self.closing:
                    messagebox.showerror("STFMR instrument disconnect", str(error), parent=self.root)
            self.stfmr_device_connection_vars[key].set("Not connected")
            self._set_stfmr_device_ui(key, False)
            if key == "kepco":
                self.stfmr_kepco_mode_var.set("Mode: --")
                self.stfmr_kepco_current_var.set("I: -- A")
                self.stfmr_kepco_voltage_var.set("V: -- V")
                # A failed zero/OFF during disconnect leaves the output possibly on.
                self.stfmr_kepco_output_var.set(
                    "OUTP: NOT CONFIRMED OFF"
                    if self.stfmr_controllers["kepco"].output_owned
                    else "OUTP: OFF"
                )
            elif key == "gauss":
                self.stfmr_gauss_field_var.set("-- G")
                self.stfmr_gauss_status_var.set("Waiting for gaussmeter connection")

        future.add_done_callback(lambda _future: self.post_ui(finished))

    def _apply_stfmr_kepco_readback(self, result: dict[str, object]) -> None:
        mode = "Current" if result["mode"] == "CURR" else "Voltage"
        self.stfmr_kepco_mode_var.set(f"Mode: {mode}")
        self.stfmr_kepco_current_var.set(
            f"I: {float(result['current_a']):+.6g} A"
        )
        self.stfmr_kepco_voltage_var.set(
            f"V: {float(result['voltage_v']):+.6g} V"
        )
        self.stfmr_kepco_output_var.set(
            "OUTP: ON" if result["output"] else "OUTP: OFF"
        )

    def apply_stfmr_kepco_output(self) -> None:
        if not self.stfmr_safety_var.get():
            messagebox.showwarning(
                "STFMR KEPCO",
                "Please tick the magnet, cooling, wiring, limits and personnel safety confirmation first.",
                parent=self.root,
            )
            return
        try:
            target = float(self.stfmr_output_target_var.get())
            limit = float(self.stfmr_output_limit_var.get())
        except ValueError:
            messagebox.showerror(
                "STFMR KEPCO", "Target and limit must be numbers.", parent=self.root
            )
            return
        mode = "CURR" if self.stfmr_output_mode_var.get() == "Current" else "VOLT"
        self.stfmr_status_var.set("Writing to KEPCO…")
        try:
            result = self.stfmr_controllers["kepco"].set_output(
                mode, target, limit
            )
        except BaseException as error:
            self.stfmr_status_var.set(f"KEPCO write failed: {error}")
            if not self.closing:
                messagebox.showerror("STFMR KEPCO", str(error), parent=self.root)
            return
        self._apply_stfmr_kepco_readback(result)
        self.stfmr_status_var.set(
            "KEPCO command sent as in the LabVIEW trace; verify the front panel and the 475"
        )

    def read_stfmr_kepco_once(self) -> None:
        if not self.stfmr_controllers["kepco"].connected:
            return
        try:
            result = self.stfmr_controllers["kepco"].readback()
        except BaseException as error:
            self.stfmr_status_var.set(f"KEPCO cached state read failed: {error}")
            return
        self._apply_stfmr_kepco_readback(result)
        self.stfmr_status_var.set("Showing the last values sent by this program, not a 4886 hardware readback")

    def zero_stfmr_kepco_output(self) -> None:
        if not self.stfmr_controllers["kepco"].connected:
            return
        # A running FMR or frequency scan is stopped first: otherwise its
        # next frequency switched the KEPCO back on (review, 2026-10-09).
        if self.stfmr_fmr_running or self.stfmr_frequency_running:
            self.stop_stfmr_fmr_scan()
        self.stfmr_status_var.set("Zeroing and turning the KEPCO output off…")
        try:
            # Explicit operator request: act even on an output this page did
            # not switch on (front panel, LabVIEW, another page, a crash).
            result = self.stfmr_controllers["kepco"].force_output_off()
        except BaseException as error:
            self.stfmr_status_var.set(f"KEPCO zeroing failed: {error}")
            if not self.closing:
                messagebox.showerror("STFMR KEPCO", str(error), parent=self.root)
            return
        self._apply_stfmr_kepco_readback(result)
        self.stfmr_status_var.set("KEPCO zeroed and output off")

    def read_stfmr_gauss_once(self) -> None:
        if (
            not self.stfmr_controllers["gauss"].connected
            or self.stfmr_poll_inflight
            or self.stfmr_fmr_running
            or self.stfmr_frequency_running
        ):
            return
        self.stfmr_poll_inflight = True
        future = self.stfmr_executor.submit(
            self.stfmr_controllers["gauss"].read_field
        )

        def finished() -> None:
            self.stfmr_poll_inflight = False
            try:
                result = future.result()
            except BaseException as error:
                self.stfmr_gauss_status_var.set(
                    f"Read failed: {short_status_error(error, 100)}"
                )
                return
            self.stfmr_gauss_field_var.set(
                f"{float(result['field']):+.8g} {result['unit']}"
            )
            self.stfmr_gauss_status_var.set("Updated")

        future.add_done_callback(lambda _future: self.post_ui(finished))

    def _stfmr_poll_timer(self) -> None:
        if self.closing or self.stfmr_closed:
            return
        if self.stfmr_gauss_auto_var.get():
            self.read_stfmr_gauss_once()
        try:
            self.stfmr_poll_after_id = self.root.after(
                STFMR_GAUSS_POLL_INTERVAL_MS, self._stfmr_poll_timer
            )
        except tk.TclError:
            self.stfmr_poll_after_id = None

    def _create_connection_indicator(
        self,
        parent: tk.Misc,
        key: str,
    ) -> tk.Canvas:
        """Create a compact grey/green instrument connection indicator."""
        canvas = tk.Canvas(
            parent,
            width=16,
            height=16,
            highlightthickness=0,
            background=self.root.cget("background"),
        )
        item = canvas.create_oval(
            3, 3, 13, 13, fill="#9aa0a6", outline="#6f757b"
        )
        self.instrument_connection_indicators[key] = (canvas, item)
        return canvas

    def _set_connection_indicator(self, key: str, connected: bool, *, fault: bool = False) -> None:
        target = self.instrument_connection_indicators.get(key)
        if target is None:
            return
        canvas, item = target
        try:
            canvas.itemconfigure(
                item,
                fill=("#e53935" if fault else "#20b15a" if connected else "#9aa0a6"),
                outline=("#a51c19" if fault else "#10783a" if connected else "#6f757b"),
            )
        except tk.TclError:
            pass

    def _configure_ui_styles(self) -> None:
        """Apply one readable visual language scaled to the active display."""
        self.ui_font_family, self.mono_font_family = configure_tk_font_system(
            self.root
        )
        # Every message box and file dialog in English (user, 2026-10-12).
        use_english_tk_dialogs(self.root)
        style = ttk.Style(self.root)
        if sys.platform == "darwin" and "clam" in style.theme_names():
            style.theme_use("clam")

        font_family = self.ui_font_family
        font_size = int(getattr(self.root, "_moke_ui_font_size", 10))
        small_font_size = int(getattr(self.root, "_moke_ui_small_font_size", 9))
        self.ui_font_size = font_size
        self.ui_small_font_size = small_font_size
        large_font_size = max(font_size + 3, int(round(15 * self.ui_scale)))
        px = self._ui_px
        palette = {
            "background": "#f4f6f8",
            "surface": "#ffffff",
            "text": "#1f2933",
            "muted": "#5f6b76",
            "border": "#cfd6dd",
            "accent": "#1769aa",
            "accent_soft": "#e8f1f8",
            "success": "#087a55",
            "warning": "#a65300",
            "status": "#eaf0f5",
        }
        self.ui_palette = palette
        self.root.configure(background=palette["background"])
        # Keep controls deliberately roomy.  Small vertical padding can clip
        # Chinese glyphs on Windows display scaling, even when the surrounding
        # panel still has plenty of free space.
        style.configure(".", font=(font_family, font_size))
        style.configure("TFrame", background=palette["background"])
        style.configure(
            "TLabelframe",
            background=palette["background"],
            bordercolor=palette["border"],
            relief="solid",
            borderwidth=1,
        )
        style.configure(
            "TLabelframe.Label",
            background=palette["background"],
            foreground=palette["text"],
            font=(font_family, font_size, "bold"),
        )
        style.configure(
            "TNotebook",
            background=palette["background"],
            borderwidth=0,
            tabmargins=(px(3, 2), px(3, 2), px(3, 2), 0),
        )
        style.configure(
            "TNotebook.Tab",
            padding=(px(14, 7), px(7, 4)),
            font=(font_family, font_size),
        )
        style.map(
            "TNotebook.Tab",
            background=[("selected", palette["surface"])],
            foreground=[("selected", palette["accent"])],
            font=[("selected", (font_family, font_size, "bold"))],
        )
        style.configure("TButton", padding=(px(9, 5), px(6, 3)))
        style.configure("Compact.TButton", padding=(px(6, 4), px(5, 3)))
        style.configure("TLabel", padding=(0, px(2, 1)))
        style.configure("TCombobox", padding=(px(5, 3), px(5, 3)))
        style.configure("TSpinbox", padding=(px(5, 3), px(5, 3)))
        style.configure("TEntry", padding=(px(5, 3), px(5, 3)))
        style.configure("TCheckbutton", padding=(px(4, 2), px(4, 2)))
        style.configure("TRadiobutton", padding=(px(4, 2), px(4, 2)))
        style.configure(
            "Accent.TButton",
            foreground=palette["accent"],
            font=(font_family, font_size, "bold"),
        )
        style.configure(
            "Metric.TLabel",
            foreground=palette["text"],
            font=(font_family, font_size, "bold"),
        )
        style.configure(
            "LargeMetric.TLabel",
            foreground=palette["text"],
            font=(font_family, large_font_size, "bold"),
        )
        style.configure("Muted.TLabel", foreground=palette["muted"])
        style.configure("Warning.TLabel", foreground=palette["warning"])
        style.configure(
            "Hint.TLabel",
            background="#fff1a8",
            foreground="#6f4500",
            padding=(px(8, 4), px(4, 2)),
            font=(font_family, font_size, "bold"),
        )
        style.configure(
            "Success.TLabel",
            foreground=palette["success"],
            font=(font_family, font_size, "bold"),
        )
        style.configure(
            "Status.TLabel",
            background=palette["status"],
            foreground=palette["text"],
            padding=(px(8, 4), px(4, 2)),
            relief="flat",
        )

    def build_stage_ui(
        self,
        parent: ttk.Frame,
        row: int,
        columnspan: int = 1,
    ) -> None:
        frame = ttk.LabelFrame(
            parent, text="Thorlabs K10CR1 analyser rotation stage (Kinesis)", padding=6
        )
        frame.grid(
            row=row,
            column=0,
            columnspan=columnspan,
            sticky="ew",
            pady=(0, 7),
        )
        # One table: labels right-aligned in column 0, entries in column 1 and
        # each row's buttons in a frame of their own from column 2, so the
        # entries and the first buttons line up down the panel and no button
        # or status text widens a column of another row.
        frame.columnconfigure(2, weight=1)
        row_pad = (5, 0)

        ttk.Label(frame, text="S/N:").grid(row=0, column=0, sticky="e", padx=(0, 4))
        self.stage_serial_entry = ttk.Entry(
            frame, textvariable=self.stage_serial_var, width=10
        )
        self.stage_serial_entry.grid(row=0, column=1, sticky="ew")
        connection = ttk.Frame(frame)
        connection.grid(row=0, column=2, sticky="ew", padx=(6, 0))
        # The operation text is last and right-aligned; in a narrow window it
        # is the one that gives way.
        connection.columnconfigure(6, weight=1)
        self.stage_connect_button = ttk.Button(
            connection, text="Connect", width=8, command=self.connect_stage
        )
        self.stage_connect_button.grid(row=0, column=0, padx=(0, 2))
        self.stage_disconnect_button = ttk.Button(
            connection, text="Disconnect", width=10, command=self.disconnect_stage
        )
        self.stage_disconnect_button.grid(row=0, column=1, padx=2)
        self.stage_read_button = ttk.Button(
            connection, text="Read status", width=11, command=self.refresh_stage_status
        )
        self.stage_read_button.grid(row=0, column=2, padx=(8, 2))
        self.stage_identify_button = ttk.Button(
            connection, text="Identify", width=8, command=self.identify_stage
        )
        self.stage_identify_button.grid(row=0, column=3, padx=2)
        self._create_connection_indicator(connection, "stage").grid(
            row=0, column=4, padx=(10, 1)
        )
        ttk.Label(connection, textvariable=self.stage_connection_var).grid(
            row=0, column=5, padx=(1, 4), sticky="w"
        )
        # At the 1101 px window only about 90 px are left for the operation
        # text once the stage is connected, so a busy message is shown cut to
        # fit, ending in "…"; stage_operation_var keeps the whole text and
        # only the display is shortened.  width=1 keeps a long message from
        # widening the row.
        stage_operation_label = ttk.Label(connection, width=1, anchor="e")
        stage_operation_label.grid(row=0, column=6, sticky="ew")
        show_trimmed(stage_operation_label, self.stage_operation_var)

        # Fixed-width readouts, sized for "Position: -359.999999°" and
        # "Homed yes | Enabled yes | Homing | ERROR", so a new reading never
        # moves the safety tick.  The tick goes below the readouts when the
        # window is too narrow for one row.
        ttk.Label(
            frame,
            textvariable=self.stage_position_var,
            style="Metric.TLabel",
            width=20,
        ).grid(row=1, column=0, sticky="w", pady=row_pad)
        state_row = ttk.Frame(frame)
        state_row.grid(row=1, column=1, columnspan=2, sticky="ew", pady=row_pad)
        stage_state_label = ttk.Label(
            state_row, textvariable=self.stage_state_var, width=39
        )
        stage_state_label.grid(row=0, column=0, sticky="w")
        self.stage_safety_check = ttk.Checkbutton(
            state_row,
            text="Analyser, cables and motion direction confirmed safe",
            variable=self.stage_safety_var,
            command=self.update_stage_controls,
        )
        self.stage_safety_check.grid(row=0, column=1, sticky="w")
        self._arrange_pair_by_width(
            state_row, stage_state_label, self.stage_safety_check, gap=10, stack_gap=5
        )

        ttk.Label(frame, text="Relative angle (°):").grid(
            row=2, column=0, sticky="e", padx=(0, 4), pady=row_pad
        )
        ttk.Entry(frame, textvariable=self.stage_relative_var, width=8).grid(
            row=2, column=1, sticky="ew", pady=row_pad
        )
        relative_button = ttk.Button(
            frame, text="Move relative", width=13, command=self.move_stage_relative
        )
        relative_button.grid(row=2, column=2, sticky="w", padx=(6, 0), pady=row_pad)

        ttk.Label(frame, text="Absolute angle (0–360°):").grid(
            row=3, column=0, sticky="e", padx=(0, 4), pady=row_pad
        )
        ttk.Entry(frame, textvariable=self.stage_absolute_var, width=8).grid(
            row=3, column=1, sticky="ew", pady=row_pad
        )
        absolute_actions = ttk.Frame(frame)
        absolute_actions.grid(row=3, column=2, sticky="w", padx=(6, 0), pady=row_pad)
        absolute_button = ttk.Button(
            absolute_actions,
            text="Go to absolute",
            width=14,
            command=self.move_stage_absolute,
        )
        absolute_button.pack(side="left")
        home_button = ttk.Button(
            absolute_actions, text="Home", width=8, command=self.home_stage
        )
        home_button.pack(side="left", padx=(10, 0))
        self.stage_stop_button = tk.Button(
            absolute_actions,
            text="Stop now",
            command=self.stop_stage,
            bg="#c62828",
            fg="white",
            activebackground="#8e0000",
            activeforeground="white",
            padx=8,
        )
        self.stage_stop_button.pack(side="left", padx=(4, 0))

        ttk.Label(frame, text="Diagnostic nudge (≤1°):").grid(
            row=4, column=0, sticky="e", padx=(0, 4), pady=row_pad
        )
        ttk.Entry(frame, textvariable=self.stage_nudge_var, width=6).grid(
            row=4, column=1, sticky="ew", pady=row_pad
        )
        # The nudge buttons, then the Home rule beside them.  The rule fills
        # the rest of the row and wraps to it, so in the default window it
        # takes a second line instead of dropping below the buttons, and the
        # label, entry, buttons and rule keep one centre line.
        nudge_row = ttk.Frame(frame)
        nudge_row.grid(row=4, column=2, sticky="ew", padx=(6, 0), pady=row_pad)
        nudge_row.columnconfigure(1, weight=1)
        nudge_buttons = ttk.Frame(nudge_row)
        nudge_buttons.grid(row=0, column=0, sticky="w")
        nudge_minus = ttk.Button(
            nudge_buttons, text="− nudge", width=8, command=lambda: self.nudge_stage(-1)
        )
        nudge_minus.pack(side="left")
        nudge_plus = ttk.Button(
            nudge_buttons, text="+ nudge", width=8, command=lambda: self.nudge_stage(1)
        )
        nudge_plus.pack(side="left", padx=(4, 0))
        nudge_rule = ttk.Label(
            nudge_row,
            text="Only diagnostic nudges are allowed before Home; relative/absolute moves need Home first.",
            foreground="#9a4d00",
        )
        nudge_rule.grid(row=0, column=1, sticky="ew", padx=(16, 0))
        nudge_rule.bind(
            "<Configure>",
            lambda event: event.widget.configure(
                wraplength=max(200, event.width - 4)
            ),
            add="+",
        )

        tip = ttk.Label(
            frame,
            text=(
                "Tip: with the polariser at 90°, extinction is best near analyser reading 23°; "
                "with the polariser at 0°, near 12°. "
                "Fine-tune around the matching position."
                "\nRed light: 650 nm, blue light: 450 nm."
                "\nObjective turret: position 2 is the 5× objective, "
                "position 4 is the 100× objective."
            ),
            style="Hint.TLabel",
        )
        tip.grid(
            row=5,
            column=0,
            columnspan=3,
            sticky="ew",
            pady=(7, 0),
        )
        # Wrap to the panel width (less the label's side padding), so the
        # first line is not cut in the default window.
        tip_inset = 2 * self._ui_px(8, 4) + 6
        tip.bind(
            "<Configure>",
            lambda event: event.widget.configure(
                wraplength=max(200, event.width - tip_inset)
            ),
            add="+",
        )
        self.stage_motion_widgets.extend(
            (relative_button, absolute_button, nudge_minus, nudge_plus, home_button)
        )

    # The MOKE magnet page's difference display, ROI editing box and display
    # rows, also on CIDWM (user, 2026-10-12).  Both pages' widgets share the
    # variables and the lists the state updates walk (one camera, one ROI).

    def _build_moke_difference_box(self, parent) -> ttk.LabelFrame:
        mode_box = ttk.LabelFrame(parent, text="MOKE difference display", padding=5)
        mode_box.columnconfigure(0, weight=1)
        ttk.Label(
            mode_box,
            textvariable=self.difference_status_var,
            style="Metric.TLabel",
        ).grid(row=0, column=0, sticky="w")

        # Mode choices, then the two buttons at natural width; the buttons
        # move under the choices when the window is too narrow for both.
        mode_row = ttk.Frame(mode_box)
        mode_row.grid(row=1, column=0, sticky="ew", pady=(3, 0))
        mode_choices = ttk.Frame(mode_row)
        mode_choices.grid(row=0, column=0, sticky="w")
        for column, (value, label) in enumerate(
            (
                ("off", "Off"),
                ("plain", "Plain difference"),
                ("tracking", "Drift tracking"),
            )
        ):
            button = ttk.Radiobutton(
                mode_choices,
                text=label,
                value=value,
                variable=self.difference_mode_var,
                command=self.select_difference_mode,
                state="disabled",
            )
            button.grid(row=0, column=column, padx=(0, 6), sticky="w")
            self.difference_mode_buttons.append(button)
        mode_actions = ttk.Frame(mode_row)
        mode_actions.grid(row=0, column=1, sticky="w")
        capture_button = ttk.Button(
            mode_actions,
            text="Recapture BG",
            command=self.capture_difference_background,
            state="disabled",
        )
        capture_button.grid(row=0, column=0, sticky="w")
        self.difference_capture_buttons.append(capture_button)
        # Wide enough for "Hide 100× marker" too, so the toggle never resizes.
        marker_button = ttk.Button(
            mode_actions,
            text="Add 100× marker",
            command=self.toggle_100x_marker,
            state="disabled",
            width=15,
        )
        marker_button.grid(row=0, column=1, sticky="w", padx=(6, 0))
        self.objective_100x_marker_buttons.append(marker_button)
        self._arrange_pair_by_width(
            mode_row, mode_choices, mode_actions, gap=0, stack_gap=3
        )

        ttk.Label(
            mode_box,
            textvariable=self.difference_detail_var,
            foreground="#9a4d00",
            wraplength=380,
        ).grid(row=2, column=0, sticky="w", pady=(3, 0))
        return mode_box

    def _build_moke_roi_edit_box(self, parent, page: str) -> ttk.LabelFrame:
        """"MOKE ROI editing" (MOKE magnet, with the magnet scan's Clear curve
        and Field).  CIDWM had it too until 2026-10-12."""
        moke = page == "MOKE"
        roi_edit = ttk.LabelFrame(parent, text="MOKE ROI editing", padding=4)
        roi_edit.columnconfigure(0, weight=1)
        roi_top = ttk.Frame(roi_edit)
        roi_top.grid(row=0, column=0, sticky="ew")
        # The ROI is one, shared by the pages; each page shows it with its
        # own labels (the 6221 page's report to its own status line).
        ttk.Label(
            roi_top, textvariable=self.moke_roi_var if moke else self.k6221_roi_var
        ).pack(side="left")
        ttk.Label(
            roi_top,
            textvariable=self.moke_roi_mean_var if moke else self.k6221_roi_mean_var,
            style="Metric.TLabel",
        ).pack(side="left", padx=(8, 0))
        # Buttons at natural width, so no label is cut.  Clear curve clears
        # the magnet scan's curve: MOKE magnet only.
        if moke:
            self.moke_clear_plot_button = ttk.Button(
                roi_top,
                text="Clear curve",
                command=self.clear_moke_plot,
                state="disabled",
            )
            self.moke_clear_plot_button.pack(side="right", padx=(4, 0))
        ttk.Button(
            roi_top,
            text="Save difference raw image",
            command=lambda: self.save_current_processed_image(page),
        ).pack(side="right", padx=(4, 0))
        ttk.Button(
            roi_top,
            text="Save raw 16-bit",
            command=lambda: self.save_current_raw_image(page),
        ).pack(side="right", padx=(4, 0))
        ttk.Button(
            roi_top,
            text="Save current display",
            command=lambda: self.save_current_display_image(page),
        ).pack(side="right", padx=(4, 0))

        roi_actions = ttk.Frame(roi_edit)
        roi_actions.grid(row=1, column=0, sticky="ew", pady=(3, 0))
        roi_toolbar = ttk.Frame(roi_actions)
        roi_toolbar.pack(side="left")
        self._populate_roi_nudge_toolbar(
            roi_toolbar,
            self.edit_moke_roi,
            self.moke_roi_edit_buttons,
            initial_state="disabled",
        )
        live_settings = ttk.Frame(roi_actions)
        live_settings.pack(side="right")
        ttk.Label(live_settings, text="Refresh s:").pack(side="left")
        ttk.Spinbox(
            live_settings,
            from_=0.05,
            to=3600.0,
            increment=0.1,
            textvariable=self.roi_live_interval_var,
            width=5,
        ).pack(side="left")
        ttk.Label(live_settings, text="Points:").pack(side="left", padx=(4, 1))
        ttk.Spinbox(
            live_settings,
            from_=10,
            to=10000,
            increment=10,
            textvariable=self.roi_live_max_points_var,
            width=6,
        ).pack(side="left")
        ttk.Button(
            live_settings,
            text="Apply",
            command=self.apply_roi_live_settings,
            width=5,
        ).pack(side="left", padx=(4, 0))

        roi_steps = ttk.Frame(roi_edit)
        roi_steps.grid(row=2, column=0, sticky="ew", pady=(4, 0))
        ttk.Label(roi_steps, text="Edit step:").pack(side="left")
        for key, unit in (("A", "°"), ("W", "px"), ("H", "px"), ("X", "px"), ("Y", "px")):
            ttk.Label(roi_steps, text=f"{key}=").pack(side="left", padx=(5, 1))
            ttk.Entry(
                roi_steps,
                textvariable=self.roi_edit_step_vars[key],
                width=5,
            ).pack(side="left")
            ttk.Label(roi_steps, text=unit).pack(side="left", padx=(1, 0))
        if moke:
            # The field source for the scan plot's top axis sits at the right
            # of this shorter line, which leaves the image buttons room above
            # and shows "Unconfirmed" whole.  The magnet scan's: MOKE magnet only.
            self.moke_field_source_combo = ttk.Combobox(
                roi_steps,
                textvariable=self.moke_field_source_var,
                values=("Unconfirmed", "Out-of-plane", "In-plane"),
                state="disabled",
                width=12,
            )
            self.moke_field_source_combo.pack(side="right")
            ttk.Label(roi_steps, text="Field:").pack(side="right", padx=(6, 1))
        return roi_edit

    def _build_moke_display_controls(self, parent) -> ttk.Frame:
        """Difference CLim, temporal average, binning, mean filter, exposure
        and the Camera Live recording."""
        display_controls = ttk.Frame(parent, padding=(5, 2, 5, 0))
        display_controls.columnconfigure(0, weight=1)
        clim_row = ttk.Frame(display_controls)
        clim_row.grid(row=0, column=0, sticky="ew", pady=(0, 4))

        clim_bar = ttk.Frame(clim_row)
        clim_bar.grid(row=0, column=0, sticky="w")
        ttk.Label(clim_bar, text="Difference CLim:").pack(side="left")
        low_entry = ttk.Entry(
            clim_bar,
            textvariable=self.difference_clim_low_var,
            width=6,
        )
        low_entry.pack(side="left")
        ttk.Label(clim_bar, text="~").pack(side="left", padx=2)
        high_entry = ttk.Entry(
            clim_bar,
            textvariable=self.difference_clim_high_var,
            width=6,
        )
        high_entry.pack(side="left")
        manual_button = ttk.Button(
            clim_bar,
            text="Manual",
            command=self.apply_difference_clim,
            state="disabled",
        )
        manual_button.pack(side="left", padx=(5, 2))
        auto_button = ttk.Button(
            clim_bar,
            text="Auto",
            command=self.clear_difference_clim,
            state="disabled",
        )
        auto_button.pack(side="left")
        histogram_button = ttk.Button(
            clim_bar,
            text="Histogram",
            command=self.show_difference_histogram,
            state="disabled",
        )
        histogram_button.pack(side="left", padx=(3, 0))
        self.difference_clim_buttons.extend(
            (manual_button, auto_button, histogram_button)
        )
        # Room for "Fixed (waiting for a difference frame)".
        ttk.Label(
            clim_bar,
            textvariable=self.difference_clim_status_var,
            style="Muted.TLabel",
            width=30,
            anchor="w",
        ).pack(side="left", padx=(5, 0))
        low_entry.bind("<Return>", lambda _event: self.apply_difference_clim())
        high_entry.bind("<Return>", lambda _event: self.apply_difference_clim())

        average_bar = ttk.Frame(clim_row)
        average_bar.grid(row=0, column=1, sticky="w")
        ttk.Label(average_bar, text="Difference temporal average:").pack(side="left")
        for count in (1, 2, 4, 8):
            button = ttk.Radiobutton(
                average_bar,
                text=f"{count} frames",
                value=count,
                variable=self.difference_temporal_average_var,
                command=self.apply_difference_display_average,
                state="disabled",
            )
            button.pack(side="left", padx=(0, 4))
            self.difference_clim_buttons.append(button)
        ttk.Label(average_bar, text="Binning:").pack(
            side="left", padx=(5, 1)
        )
        for factor in (1, 2, 4, 8):
            button = ttk.Radiobutton(
                average_bar,
                text=f"{factor}×{factor}",
                value=factor,
                variable=self.difference_spatial_binning_var,
                command=self.apply_difference_display_average,
                state="disabled",
            )
            button.pack(side="left", padx=(0, 3))
            self.difference_clim_buttons.append(button)
        self._arrange_pair_by_width(
            clim_row, clim_bar, average_bar, gap=12, stack_gap=4
        )

        filter_row = ttk.Frame(display_controls)
        filter_row.grid(row=1, column=0, sticky="ew", pady=(0, 4))
        filter_bar = ttk.Frame(filter_row)
        filter_bar.grid(row=0, column=0, sticky="w")
        ttk.Label(filter_bar, text="Mean filter:").pack(side="left")
        for filter_size, label in ((1, "Off"), (2, "2×2"), (4, "4×4")):
            button = ttk.Radiobutton(
                filter_bar,
                text=label,
                value=filter_size,
                variable=self.difference_mean_filter_var,
                command=self.apply_difference_display_average,
                state="disabled",
            )
            button.pack(side="left", padx=(0, 4))
            self.difference_clim_buttons.append(button)
        ttk.Label(
            filter_bar,
            text="Sliding-window mean (applies to ROI, scans and processed images)",
            style="Muted.TLabel",
        ).pack(side="left", padx=(5, 0))

        exposure_bar = ttk.Frame(filter_row)
        exposure_bar.grid(row=0, column=1, sticky="w")
        ttk.Label(exposure_bar, text="Exposure ms:").pack(
            side="left", padx=(0, 2)
        )
        exposure_entry = ttk.Entry(
            exposure_bar,
            textvariable=self.camera_exposure_ms_var,
            width=7,
        )
        exposure_entry.pack(side="left")
        exposure_button = ttk.Button(
            exposure_bar,
            text="Apply exposure",
            command=self.apply_camera_exposure,
            state="disabled",
        )
        exposure_button.pack(side="left", padx=(3, 2))
        self.difference_clim_buttons.append(exposure_button)
        exposure_entry.bind(
            "<Return>", lambda _event: self.apply_camera_exposure()
        )
        ttk.Label(
            exposure_bar,
            textvariable=self.camera_exposure_status_var,
            style="Muted.TLabel",
        ).pack(side="left", padx=(2, 0))
        self._arrange_pair_by_width(
            filter_row, filter_bar, exposure_bar, gap=12, stack_gap=4
        )

        # Its own line, with room for the recording statistics.
        video_bar = ttk.Frame(display_controls)
        video_bar.grid(row=2, column=0, sticky="ew")
        ttk.Label(video_bar, text="Camera Live 8-bit recording: FPS").pack(side="left")
        ttk.Entry(
            video_bar,
            textvariable=self.camera_video_fps_var,
            width=5,
        ).pack(side="left", padx=(3, 4))
        # Fits "Start recording" and "Stop recording", so the toggle never
        # resizes the button.
        video_button = ttk.Button(
            video_bar,
            text="Start recording",
            command=self.toggle_camera_video_recording,
            state="disabled",
            width=13,
        )
        video_button.pack(side="left")
        self.camera_video_buttons.append(video_button)
        if self.camera_video_button is None:
            self.camera_video_button = video_button
        ttk.Label(
            video_bar,
            textvariable=self.camera_video_status_var,
            style="Muted.TLabel",
        ).pack(side="left", padx=(7, 0))
        return display_controls

    def build_difference_ui(self) -> None:
        outer = ttk.Frame(self.difference_tab, padding=6)
        outer.grid(row=0, column=0, sticky="nsew")
        outer.columnconfigure(0, weight=1)
        # Spare window height goes to the plots (row 4), as on the 6221 page,
        # so they fill the page down to the status line.  In a short window
        # the plots give way first and the status line stays on screen.
        outer.rowconfigure(4, weight=1)

        # The ports keep their natural width and the display box takes the
        # rest, so the display box's width never depends on its own layout.
        top_row = ttk.Frame(outer)
        top_row.grid(row=0, column=0, sticky="ew", pady=(0, 3))
        top_row.columnconfigure(0, weight=1)

        mode_box = self._build_moke_difference_box(top_row)
        mode_box.grid(row=0, column=0, sticky="nsew", padx=(0, 3))

        connection = ttk.LabelFrame(top_row, text="KEPCO and gaussmeter ports", padding=5)
        connection.grid(row=0, column=1, sticky="nsew", padx=(3, 0))
        connection.columnconfigure(2, weight=1)
        connection.columnconfigure(5, weight=1)
        for row, (bop_label, bop_key, gauss_label, gauss_key) in enumerate(
            (
                ("Out-of-plane magnet", "OUT_BOP", "Out-of-plane gaussmeter", "OUT_GAUSS"),
                ("In-plane magnet", "IN_BOP", "In-plane gaussmeter", "IN_GAUSS"),
            )
        ):
            ttk.Label(connection, text=f"{bop_label}:").grid(
                row=row, column=0, sticky="e", padx=(0, 2), pady=1
            )
            self._create_connection_indicator(
                connection, f"magnet_{bop_key}"
            ).grid(row=row, column=1, padx=(0, 1), pady=1)
            bop_box = ttk.Combobox(
                connection,
                textvariable=self.magnet_port_vars[bop_key],
                width=10,
                state="normal",
            )
            bop_box.grid(row=row, column=2, sticky="ew", padx=(0, 5), pady=1)
            self.magnet_port_combos[bop_key] = bop_box
            ttk.Label(connection, text=f"{gauss_label}:").grid(
                row=row, column=3, sticky="e", padx=(0, 2), pady=1
            )
            self._create_connection_indicator(
                connection, f"magnet_{gauss_key}"
            ).grid(row=row, column=4, padx=(0, 1), pady=1)
            gauss_box = ttk.Combobox(
                connection,
                textvariable=self.magnet_port_vars[gauss_key],
                width=10,
                state="normal",
            )
            gauss_box.grid(row=row, column=5, sticky="ew", pady=1)
            self.magnet_port_combos[gauss_key] = gauss_box

        # The connection summary wraps beside the buttons, three lines once
        # connected, so the port box keeps the width of its port table and
        # the display box beside it never resizes.  The row keeps room for
        # three lines, so connecting does not push the page down, and the
        # buttons stay at its top.
        button_row = ttk.Frame(connection)
        button_row.grid(row=2, column=0, columnspan=6, sticky="new", pady=(2, 0))
        ttk.Button(
            button_row, text="Refresh", command=self.refresh_magnet_ports, width=7
        ).pack(side="left", anchor="n", padx=2)
        self.magnet_connect_button = ttk.Button(
            button_row, text="Connect", command=self.connect_magnets, width=8
        )
        self.magnet_connect_button.pack(side="left", anchor="n", padx=2)
        self.magnet_disconnect_button = ttk.Button(
            button_row, text="Disconnect", command=self.disconnect_magnets, width=10
        )
        self.magnet_disconnect_button.pack(side="left", anchor="n", padx=2)
        connection_summary = ttk.Label(
            button_row,
            textvariable=self.magnet_connection_var,
            wraplength=self._ui_px(280),
        )
        connection_summary.pack(side="left", padx=(6, 0))
        # Its one-line height ("Not connected") plus two more lines, plus the
        # row's 2 px top gap.
        summary_line = tkfont.Font(
            root=self.root, family=self.ui_font_family, size=self.ui_font_size
        ).metrics("linespace")
        connection.rowconfigure(
            2,
            minsize=int(connection_summary.winfo_reqheight()) + 2 * summary_line + 2,
        )

        safety = ttk.Frame(outer, padding=(2, 2))
        safety.grid(row=1, column=0, sticky="ew")
        safety.columnconfigure(0, weight=1)
        ttk.Checkbutton(
            safety,
            text="Magnet polarity, cooling, wiring and personnel safety confirmed (non-zero current allowed)",
            variable=self.magnet_safety_var,
            command=self._update_magnet_controls,
        ).grid(row=0, column=0, sticky="w")
        self.magnet_initialize_button = ttk.Button(
            safety,
            text="Enable/zero active path",
            command=self.initialize_magnets,
        )
        self.magnet_initialize_button.grid(row=0, column=1, padx=3)
        self.magnet_zero_button = tk.Button(
            safety,
            text="Zero both now",
            command=self.zero_both_magnets,
            bg="#d70018",
            fg="white",
            activebackground="#a80012",
            activeforeground="white",
            padx=6,
            pady=1,
        )
        self.magnet_zero_button.grid(row=0, column=2)

        # The selector, then its warning; the warning moves under the
        # selector, still whole, when the window is too narrow for both.
        switch_row = ttk.Frame(safety)
        switch_row.grid(row=1, column=0, columnspan=3, sticky="ew", pady=(4, 0))
        switch_choices = ttk.Frame(switch_row)
        switch_choices.grid(row=0, column=0, sticky="w")
        ttk.Label(
            switch_choices,
            text="Physical selector:",
            style="Warning.TLabel",
        ).pack(side="left")
        for value, text in (
            ("Unconfirmed", "Unconfirmed"),
            ("Out-of-plane", "Physically set to out-of-plane"),
            ("In-plane", "Physically set to in-plane"),
        ):
            button = ttk.Radiobutton(
                switch_choices,
                text=text,
                value=value,
                variable=self.magnet_switch_var,
                command=self.select_magnet_switch,
            )
            button.pack(side="left", padx=(3, 0))
            self.magnet_switch_buttons.append(button)
        switch_warning = ttk.Label(
            switch_row,
            text="Zero both paths before switching; the GUI must match the hardware",
            style="Warning.TLabel",
        )
        switch_warning.grid(row=0, column=1, sticky="w")
        self._arrange_pair_by_width(
            switch_row, switch_choices, switch_warning, gap=10, stack_gap=2
        )

        control_row = ttk.Frame(outer)
        control_row.grid(row=2, column=0, sticky="ew", pady=(2, 3))
        control_row.columnconfigure(0, weight=1, uniform="moke_controls")
        control_row.columnconfigure(1, weight=1, uniform="moke_controls")

        channel_area = ttk.Frame(control_row)
        channel_area.grid(row=0, column=0, sticky="nsew", padx=(0, 3))
        channel_area.columnconfigure(0, weight=1)
        self._build_magnet_channel_ui(channel_area, "OUT", 0)
        self._build_magnet_channel_ui(channel_area, "IN", 1)

        read_row = ttk.Frame(channel_area, padding=(1, 2))
        read_row.grid(row=2, column=0, sticky="ew")
        self.magnet_read_button = ttk.Button(
            read_row,
            text="Read active path",
            command=self.read_all_magnets,
        )
        self.magnet_read_button.pack(side="left", padx=(0, 4))
        ttk.Checkbutton(
            read_row,
            text="Continuous",
            variable=self.magnet_auto_poll_var,
            command=self._magnet_poll_changed,
        ).pack(side="left")
        ttk.Label(read_row, text="Interval s:").pack(side="left", padx=(5, 1))
        ttk.Spinbox(
            read_row,
            from_=0.2,
            to=10.0,
            increment=0.1,
            textvariable=self.magnet_poll_interval_var,
            width=5,
        ).pack(side="left")

        scan_box = ttk.LabelFrame(
            control_row, text="Magnet current scan and ROI acquisition", padding=5
        )
        scan_box.grid(row=0, column=1, sticky="nsew", padx=(3, 0))
        scan_box.columnconfigure(0, weight=1)
        # One aligned table: each label right-aligned against its field and
        # the fields of a column the same width.  It has its own frame, so
        # the wider button row below does not stretch its columns.
        scan_params = ttk.Frame(scan_box)
        scan_params.grid(row=0, column=0, sticky="w")
        ttk.Label(scan_params, text="Start A:").grid(
            row=0, column=0, sticky="e", padx=(0, 3)
        )
        ttk.Entry(
            scan_params, textvariable=self.magnet_scan_start_current_var, width=7
        ).grid(row=0, column=1, sticky="ew", padx=(0, 8))
        ttk.Label(scan_params, text="End A:").grid(
            row=0, column=2, sticky="e", padx=(0, 3)
        )
        ttk.Entry(
            scan_params, textvariable=self.magnet_scan_end_current_var, width=7
        ).grid(row=0, column=3, sticky="ew")

        ttk.Label(scan_params, text="Step A:").grid(
            row=1, column=0, sticky="e", padx=(0, 3), pady=(3, 0)
        )
        ttk.Entry(
            scan_params, textvariable=self.magnet_scan_step_current_var, width=7
        ).grid(row=1, column=1, sticky="ew", padx=(0, 8), pady=(3, 0))
        ttk.Label(scan_params, text="Loop:").grid(
            row=1, column=2, sticky="e", padx=(0, 3), pady=(3, 0)
        )
        ttk.Spinbox(
            scan_params,
            from_=1,
            to=1000,
            increment=1,
            textvariable=self.magnet_scan_loop_var,
            width=5,
        ).grid(row=1, column=3, sticky="ew", pady=(3, 0))

        ttk.Label(scan_params, text="Settle s:").grid(
            row=2, column=0, sticky="e", padx=(0, 3), pady=(3, 0)
        )
        ttk.Entry(
            scan_params, textvariable=self.magnet_scan_settle_var, width=7
        ).grid(row=2, column=1, sticky="ew", padx=(0, 8), pady=(3, 0))
        ttk.Label(scan_params, text="Acquire s:").grid(
            row=2, column=2, sticky="e", padx=(0, 3), pady=(3, 0)
        )
        ttk.Entry(
            scan_params, textvariable=self.magnet_scan_collect_var, width=7
        ).grid(row=2, column=3, sticky="ew", pady=(3, 0))

        # The three buttons, then the image option; the option moves under
        # the buttons when the box is too narrow for both.
        scan_buttons = ttk.Frame(scan_box)
        scan_buttons.grid(row=1, column=0, sticky="ew", pady=(4, 0))
        scan_actions = ttk.Frame(scan_buttons)
        scan_actions.grid(row=0, column=0, sticky="w")
        self.magnet_scan_start_button = ttk.Button(
            scan_actions, text="Start scan", command=self.start_magnet_scan, width=10
        )
        self.magnet_scan_start_button.pack(side="left", padx=(0, 3))
        self.magnet_scan_stop_button = ttk.Button(
            scan_actions, text="Stop/zero", command=self.stop_magnet_scan, width=9
        )
        self.magnet_scan_stop_button.pack(side="left", padx=3)
        self.magnet_scan_save_button = ttk.Button(
            scan_actions,
            text="Save CSV + PNG",
            command=self.save_magnet_scan_csv,
            width=16,
        )
        self.magnet_scan_save_button.pack(side="left", padx=3)
        self.magnet_save_images_check = ttk.Checkbutton(
            scan_buttons,
            text="Save processed images too",
            variable=self.magnet_save_images_var,
            command=self.configure_magnet_image_saving,
        )
        self.magnet_save_images_check.grid(row=0, column=1, sticky="w")
        self._arrange_pair_by_width(
            scan_buttons,
            scan_actions,
            self.magnet_save_images_check,
            gap=8,
            stack_gap=4,
        )
        progress_row = ttk.Frame(scan_box)
        progress_row.grid(row=2, column=0, sticky="ew", pady=(5, 0))
        progress_row.columnconfigure(0, weight=1)
        self.magnet_scan_progress = ttk.Progressbar(
            progress_row,
            mode="determinate",
            maximum=1,
            value=0,
            length=150,
        )
        self.magnet_scan_progress.grid(row=0, column=0, sticky="ew", padx=(0, 7))
        ttk.Label(
            progress_row,
            textvariable=self.magnet_scan_eta_var,
            foreground="#0068b5",
            font=(self.ui_font_family, self.ui_small_font_size, "bold"),
        ).grid(row=0, column=1, sticky="e")
        scan_path_label = ttk.Label(
            scan_box,
            text=(
                "Path: start→end→start; returns to start on completion, zeroed on stop/error."
            ),
            foreground="#9a4d00",
            wraplength=420,
        )
        scan_path_label.grid(row=3, column=0, sticky="w", pady=(2, 0))
        scan_folder_label = ttk.Label(
            scan_box,
            textvariable=self.magnet_image_directory_var,
            foreground="#555555",
            wraplength=350,
        )
        scan_folder_label.grid(row=4, column=0, sticky="w", pady=(2, 0))
        scan_wrap = {"width": None}

        def wrap_scan_notes(event) -> None:
            # Both notes wrap at the box's inner width (less its border and
            # padding): one line in a wide window, whole lines in a narrow one.
            width = max(200, int(event.width) - 20)
            if scan_wrap["width"] == width:
                return
            scan_wrap["width"] = width
            scan_path_label.configure(wraplength=width)
            scan_folder_label.configure(wraplength=width)

        scan_box.bind("<Configure>", wrap_scan_notes, add="+")

        roi_edit = self._build_moke_roi_edit_box(outer, "MOKE")
        roi_edit.grid(row=3, column=0, sticky="ew", pady=(0, 3))

        data_frame = ttk.Frame(outer)
        data_frame.grid(row=4, column=0, sticky="nsew")
        data_frame.rowconfigure(1, weight=1)
        # The live ROI trace stays the primary, wider plot, as on the 6221
        # page.  The scan plot is never narrower than its title.
        plot_title = "Magnet current vs ROI mean intensity (top axis: Magnetic field (Gs))"
        plot_title_width = tkfont.Font(
            root=self.root,
            family=self.ui_font_family,
            size=self.ui_font_size,
            weight="bold",
        ).measure(plot_title) + self._ui_px(24)
        data_frame.columnconfigure(0, weight=2, uniform="moke_bottom_plots")
        data_frame.columnconfigure(
            1, weight=1, uniform="moke_bottom_plots", minsize=plot_title_width
        )

        # Display, exposure and recording settings run across the page above
        # both plots.  Two groups share a line when both fit; each pair stacks
        # by itself when the window is too narrow.  Status texts that change
        # sit at the end of a line or in a fixed-width box, so they never
        # push other controls.
        display_controls = self._build_moke_display_controls(data_frame)
        display_controls.grid(
            row=0, column=0, columnspan=2, sticky="ew", pady=(0, 4)
        )
        # Once, for every page's CLim boxes (they share the variables).
        self.difference_clim_low_var.trace_add(
            "write", self._schedule_difference_clim_live_update
        )
        self.difference_clim_high_var.trace_add(
            "write", self._schedule_difference_clim_live_update
        )

        intensity_box = ttk.LabelFrame(
            data_frame, text="ROI mean intensity vs time (live)", padding=6
        )
        intensity_box.grid(row=1, column=0, sticky="nsew", padx=(0, 5))
        intensity_box.rowconfigure(0, weight=1)
        intensity_box.columnconfigure(0, weight=1)
        self.moke_intensity_canvas = tk.Canvas(
            intensity_box,
            bg="#fbfcfd",
            highlightthickness=1,
            highlightbackground="#cfd6dd",
            height=self._ui_px(200, 125, canvas=True),
        )
        self.moke_intensity_canvas.grid(row=0, column=0, sticky="nsew")
        self.moke_intensity_canvas.bind(
            "<Configure>", lambda _event: self._redraw_live_intensity_plots()
        )

        plot_box = ttk.LabelFrame(
            data_frame,
            text=plot_title,
            padding=6,
        )
        plot_box.grid(row=1, column=1, sticky="nsew")
        plot_box.rowconfigure(0, weight=1)
        plot_box.columnconfigure(0, weight=1)
        self.moke_plot_canvas = tk.Canvas(
            plot_box,
            bg="#fbfcfd",
            highlightthickness=1,
            highlightbackground="#cfd6dd",
            height=self._ui_px(200, 125, canvas=True),
        )
        self.moke_plot_canvas.grid(row=0, column=0, sticky="nsew")
        self.moke_plot_canvas.bind(
            "<Configure>", lambda _event: self._redraw_moke_plot()
        )
        self.moke_field_source_var.trace_add(
            "write", lambda *_args: self._redraw_moke_plot()
        )
        ttk.Label(
            outer,
            textvariable=self.magnet_status_var,
            style="Status.TLabel",
            anchor="w",
        ).grid(row=5, column=0, sticky="ew", pady=(4, 0))
        self._update_magnet_scan_controls()

    def _build_magnet_channel_ui(self, parent, key: str, row: int) -> None:
        label = MAGNET_CHANNEL_LABELS[key]
        bop_port = "COM14" if key == "OUT" else "COM12"
        gauss_port = "COM13" if key == "OUT" else "COM15"
        panel = ttk.LabelFrame(
            parent,
            text=f"{label} path (BOP {bop_port}; Gauss {gauss_port})",
            padding=4,
        )
        panel.grid(
            row=row,
            column=0,
            sticky="ew",
            pady=(0, 2) if row == 0 else 0,
        )
        # One aligned table: labels right-aligned against their fields, both
        # fields the same width, and each button column one width, so Write
        # sits over Down, Flip over Up and Zero current over Zero field.  The
        # vista theme makes a button with no width at least 11 characters
        # wide (about 127 px), so the short buttons get widths that just fit
        # their text; Zero current needs the 11 characters.  Four button
        # columns fit the half-page panel in the default window with the
        # fields and the current readout at full width; a fifth would not.
        ttk.Label(panel, text="Target A:").grid(row=0, column=0, sticky="e")
        target_entry = ttk.Entry(
            panel, textvariable=self.magnet_target_vars[key], width=7
        )
        target_entry.grid(row=0, column=1, sticky="ew", padx=(1, 3))
        write_button = ttk.Button(
            panel,
            text="Write",
            command=lambda selected=key: self.set_magnet_current(selected),
            width=5,
        )
        write_button.grid(row=0, column=2, sticky="ew", padx=1)
        flip_button = ttk.Button(
            panel,
            text="Flip",
            command=lambda selected=key: self.flip_magnet_current(selected),
            width=5,
        )
        flip_button.grid(row=0, column=3, sticky="ew", padx=1)
        zero_button = ttk.Button(
            panel,
            text="Zero current",
            command=lambda selected=key: self.zero_magnet(selected),
        )
        zero_button.grid(row=0, column=4, sticky="ew", padx=(1, 0))
        self.magnet_channel_control_widgets[key] = {
            "target": target_entry,
            "write": write_button,
            "flip": flip_button,
            "zero": zero_button,
        }
        ttk.Label(panel, text="I:").grid(row=1, column=0, sticky="e", pady=(2, 0))
        ttk.Label(
            panel,
            textvariable=self.magnet_current_vars[key],
            style="Metric.TLabel",
        ).grid(row=1, column=1, sticky="w", pady=(2, 0))
        ttk.Label(panel, text="Field:").grid(
            row=1, column=2, sticky="e", pady=(2, 0)
        )
        ttk.Label(
            panel,
            textvariable=self.magnet_field_vars[key],
            style="Metric.TLabel",
        ).grid(row=1, column=3, columnspan=2, sticky="w", pady=(2, 0))
        ttk.Label(panel, text="Step A:").grid(
            row=2, column=0, sticky="e", pady=(3, 0)
        )
        step_entry = ttk.Entry(
            panel,
            textvariable=self.magnet_manual_step_vars[key],
            width=7,
        )
        step_entry.grid(row=2, column=1, sticky="ew", padx=(1, 3), pady=(3, 0))
        down_button = ttk.Button(
            panel,
            text="↓ Down",
            command=lambda selected=key: self.step_magnet_current(selected, -1),
            width=7,
        )
        down_button.grid(row=2, column=2, sticky="ew", padx=1, pady=(3, 0))
        up_button = ttk.Button(
            panel,
            text="↑ Up",
            command=lambda selected=key: self.step_magnet_current(selected, 1),
            width=5,
        )
        up_button.grid(row=2, column=3, sticky="ew", padx=1, pady=(3, 0))
        field_zero_button = ttk.Button(
            panel,
            text="Zero field",
            command=lambda selected=key: self.zero_magnet_field(selected),
            width=8,
        )
        field_zero_button.grid(
            row=2, column=4, sticky="ew", padx=(1, 0), pady=(3, 0)
        )
        self.magnet_channel_control_widgets[key].update(
            {
                "field_zero": field_zero_button,
                "step": step_entry,
                "down": down_button,
                "up": up_button,
            }
        )
        # Spare width goes to an empty last column, so the table stays packed
        # to the left.  Only in a window narrower than the table do the fields
        # (column 1) give way, instead of a button being cut off.
        panel.columnconfigure(1, weight=1)
        panel.columnconfigure(5, weight=1000)

    def build_keithley_ui(self) -> None:
        outer = ttk.Frame(self.keithley_tab, padding=7)
        outer.grid(row=0, column=0, sticky="nsew")
        outer.columnconfigure(0, weight=1)
        # Spare window height goes to the plots (row 4), so they fill the
        # page down to the status line.
        outer.rowconfigure(4, weight=1)

        # As on the STFMR and PPMS pages: the instrument connection on the
        # left and the source output on the right, side by side when both
        # fit, else stacked.
        top = ttk.Frame(outer)
        top.grid(row=0, column=0, sticky="ew", pady=(0, 5))
        top.columnconfigure(1, weight=1)

        instruments = ttk.LabelFrame(
            top, text="MOKE-24 instrument connection", padding=self._ui_px(6, 4)
        )
        instruments.grid(row=0, column=0, sticky="nsew", padx=(0, 4))
        device = ttk.Frame(instruments)
        device.grid(row=0, column=0, sticky="ew", pady=1)
        # The rack row of the other pages: name, address, Connect,
        # Disconnect, lamp and state, then this instrument's settings.  The
        # address gives way first if the row is too narrow.
        device.columnconfigure(1, weight=1)
        device.columnconfigure(6, weight=1000)
        ttk.Label(device, text="Keithley:", width=11, anchor="e").grid(
            row=0, column=0, sticky="e"
        )
        ttk.Entry(
            device, textvariable=self.keithley_resource_var, width=18
        ).grid(row=0, column=1, sticky="w", padx=(0, 4))
        self.keithley_connect_button = ttk.Button(
            device, text="Connect", width=8, command=self.connect_keithley
        )
        self.keithley_connect_button.grid(row=0, column=2, padx=1)
        self.keithley_disconnect_button = ttk.Button(
            device, text="Disconnect", width=10, command=self.disconnect_keithley
        )
        self.keithley_disconnect_button.grid(row=0, column=3, padx=1)
        self._create_connection_indicator(device, "keithley2410").grid(
            row=0, column=4, padx=(5, 1)
        )
        ttk.Label(
            device, textvariable=self.keithley_connection_var, width=13, anchor="w"
        ).grid(row=0, column=5, sticky="w", padx=(1, 0))
        # Its settings on the line below, under the address, as the Gate-VI
        # rows do in a narrow window; one line was too wide to sit beside
        # the output panel.  Which SourceMeter: its range above 20 V, the
        # current allowed there and the voltage limit and OVP follow the
        # choice (KEITHLEY_MODELS); fixed while connected.
        settings = ttk.Frame(device)
        settings.grid(row=1, column=1, columnspan=5, sticky="w", pady=(4, 0))
        ttk.Label(settings, text="Model:").pack(side="left", padx=(0, 3))
        self.keithley_model_combo = ttk.Combobox(
            settings, textvariable=self.keithley_model_var,
            values=tuple(KEITHLEY_MODELS), state="readonly", width=6,
        )
        self.keithley_model_combo.pack(side="left", padx=(0, 10))
        self.keithley_model_combo.bind("<<ComboboxSelected>>", lambda event: self._update_keithley_controls())
        ttk.Label(settings, text="Current limit (A):").pack(side="left", padx=(0, 3))
        ttk.Entry(
            settings, textvariable=self.keithley_compliance_var, width=9
        ).pack(side="left")

        # The source output, as the STFMR page's KEPCO output: the safety
        # check, the manual controls with the red off button, the readback.
        output = ttk.LabelFrame(top, text="Keithley output", padding=8)
        output.grid(row=0, column=1, sticky="nsew")
        output.columnconfigure(10, weight=1)
        for panel_row in range(3):
            output.rowconfigure(panel_row, weight=1)
        ttk.Checkbutton(
            output,
            text="Wiring, current limit and manual/scan voltage range confirmed safe",
            variable=self.keithley_safety_var,
            command=self._update_keithley_controls,
        ).grid(row=0, column=0, columnspan=11, sticky="w", pady=(0, 6))
        ttk.Label(output, text="Manual V:").grid(row=1, column=0, sticky="e")
        ttk.Entry(
            output,
            textvariable=self.keithley_manual_voltage_var,
            width=9,
        ).grid(row=1, column=1, padx=(0, 4))
        manual_write = ttk.Button(
            output,
            text="Write",
            command=self.write_keithley_manual_voltage,
            width=7,
        )
        manual_write.grid(row=1, column=2, padx=(0, 3))
        manual_flip = ttk.Button(
            output,
            text="Flip",
            command=self.flip_keithley_manual_voltage,
            width=7,
        )
        manual_flip.grid(row=1, column=3, padx=(0, 3))
        self.keithley_manual_zero_button = ttk.Button(
            output,
            text="Zero",
            command=lambda: self._submit_keithley_manual_voltage(
                0.0, "zero", require_safety=False
            ),
            width=7,
        )
        self.keithley_manual_zero_button.grid(row=1, column=4, padx=(0, 10))
        ttk.Label(output, text="Step V:").grid(row=1, column=5, sticky="e")
        ttk.Entry(
            output,
            textvariable=self.keithley_manual_step_var,
            width=8,
        ).grid(row=1, column=6, padx=(0, 4))
        manual_down = ttk.Button(
            output,
            text="↓ Down",
            command=lambda: self.step_keithley_manual_voltage(-1),
            width=8,
        )
        manual_down.grid(row=1, column=7, padx=(0, 3))
        manual_up = ttk.Button(
            output,
            text="↑ Up",
            command=lambda: self.step_keithley_manual_voltage(1),
            width=8,
        )
        manual_up.grid(row=1, column=8)
        self.keithley_manual_buttons.extend(
            (manual_write, manual_flip, manual_down, manual_up)
        )
        self.keithley_off_button = tk.Button(
            output,
            text=f"{self.keithley_model_var.get()} zero / output off",
            command=self.stop_keithley_scan,
            bg="#d70018",
            fg="white",
            activebackground="#a80012",
            activeforeground="white",
            padx=12,
            pady=2,
        )
        self.keithley_off_button.grid(row=1, column=9, padx=(10, 2), sticky="w")
        ttk.Label(output, textvariable=self.keithley_voltage_var, anchor="w").grid(
            row=2, column=0, columnspan=9, sticky="ew", pady=(7, 0)
        )
        self._arrange_pair_by_width(top, instruments, output)

        # The limit follows the model (KEITHLEY_MODELS); set in
        # _update_keithley_controls.  Full page width, wrapped when narrower.
        hazard = ttk.Label(
            outer, textvariable=self.keithley_hazard_var, foreground="#a34b00",
        )
        hazard.grid(row=1, column=0, sticky="ew", pady=(0, 5))
        hazard.bind(
            "<Configure>",
            lambda event: event.widget.configure(
                wraplength=max(200, event.width - 4)
            ),
        )

        # The voltage scan beside ROI editing in a wide window, stacked in
        # the default one.
        acquisition = ttk.Frame(outer)
        acquisition.grid(row=2, column=0, sticky="ew", pady=(0, 7))
        acquisition.columnconfigure(1, weight=1)
        scan = ttk.LabelFrame(
            acquisition, text="Voltage scan and ROI acquisition", padding=8
        )
        scan.grid(row=0, column=0, sticky="nsew")
        ttk.Label(scan, text="Start V:").grid(row=0, column=0)
        ttk.Entry(scan, textvariable=self.keithley_start_var, width=8).grid(
            row=0, column=1, padx=(0, 8)
        )
        ttk.Label(scan, text="End V:").grid(row=0, column=2)
        ttk.Entry(scan, textvariable=self.keithley_end_var, width=8).grid(
            row=0, column=3, padx=(0, 8)
        )
        ttk.Label(scan, text="Step V:").grid(row=0, column=4)
        ttk.Entry(scan, textvariable=self.keithley_step_var, width=8).grid(
            row=0, column=5, padx=(0, 12)
        )
        ttk.Label(scan, text="Settle s:").grid(row=0, column=6)
        ttk.Entry(scan, textvariable=self.keithley_settle_var, width=7).grid(
            row=0, column=7, padx=(0, 8)
        )
        ttk.Label(scan, text="Acquire s:").grid(row=0, column=8)
        ttk.Entry(scan, textvariable=self.keithley_collect_var, width=7).grid(
            row=0, column=9
        )
        ttk.Label(scan, textvariable=self.keithley_roi_var).grid(
            row=1, column=0, columnspan=6, sticky="w", pady=(8, 0)
        )
        self.keithley_save_images_check = ttk.Checkbutton(
            scan,
            text="Save processed images too",
            variable=self.keithley_save_images_var,
            command=self.configure_keithley_image_saving,
        )
        self.keithley_save_images_check.grid(
            row=1, column=6, columnspan=4, sticky="e", pady=(8, 0)
        )
        # The buttons in a row of their own, so they do not widen the
        # parameter columns above them.
        scan_actions = ttk.Frame(scan)
        scan_actions.grid(row=2, column=0, columnspan=10, sticky="w", pady=(8, 0))
        self.keithley_start_button = ttk.Button(
            scan_actions, text="Start round-trip scan", command=self.start_keithley_scan
        )
        self.keithley_start_button.pack(side="left", padx=(0, 4))
        self.keithley_stop_button = ttk.Button(
            scan_actions, text="Stop scan", command=self.stop_keithley_scan
        )
        self.keithley_stop_button.pack(side="left", padx=(0, 4))
        self.keithley_save_button = ttk.Button(
            scan_actions, text="Save CSV + PNG", command=self.save_keithley_csv
        )
        self.keithley_save_button.pack(side="left")
        progress_row = ttk.Frame(scan)
        progress_row.grid(row=3, column=0, columnspan=10, sticky="ew", pady=(6, 0))
        progress_row.columnconfigure(0, weight=1)
        self.keithley_scan_progress = ttk.Progressbar(
            progress_row,
            mode="determinate",
            maximum=1,
            value=0,
            length=180,
        )
        self.keithley_scan_progress.grid(row=0, column=0, sticky="ew", padx=(0, 8))
        ttk.Label(
            progress_row,
            textvariable=self.keithley_scan_eta_var,
            style="Success.TLabel",
        ).grid(row=0, column=1, sticky="e")
        ttk.Label(
            scan,
            textvariable=self.keithley_image_directory_var,
            foreground="#555555",
        ).grid(row=4, column=0, columnspan=10, sticky="w", pady=(4, 0))

        roi_edit = ttk.LabelFrame(acquisition, text="ROI editing", padding=7)
        roi_edit.grid(row=0, column=1, sticky="nsew")
        # Spare width goes to the empty column 9.  Without a weight, a
        # full-width row (the toolbar with the ROI mean, or the recording bar)
        # that grows with its text spreads the difference over all ten
        # columns and pushes the live settings apart.
        roi_edit.columnconfigure(9, weight=1)
        actions = ttk.Frame(roi_edit)
        actions.grid(row=0, column=0, columnspan=10, sticky="ew")
        toolbar = ttk.Frame(actions)
        toolbar.pack(side="left")
        self._populate_roi_nudge_toolbar(
            toolbar,
            self.edit_2410_roi,
            self.keithley_roi_edit_buttons,
        )
        # Close to one width for every reading (a negative width is a
        # minimum).  A longer message ("waiting for the current difference
        # frame") wraps to a second line: the pair below is re-checked only on
        # a resize, so a wider ROI editing box would be cut beside the scan.
        ttk.Label(
            actions,
            textvariable=self.keithley_roi_mean_var,
            style="Metric.TLabel",
            width=-30,
            wraplength=self._ui_px(240),
        ).pack(side="right", padx=(8, 2))
        roi_steps = ttk.Frame(roi_edit)
        roi_steps.grid(row=1, column=0, columnspan=10, sticky="w", pady=(6, 0))
        ttk.Label(roi_steps, text="Step:", style="Muted.TLabel").pack(side="left")
        for key, unit in (("A", "°"), ("W", "px"), ("H", "px"), ("X", "px"), ("Y", "px")):
            ttk.Label(roi_steps, text=f"{key}=").pack(side="left", padx=(5, 1))
            ttk.Entry(
                roi_steps,
                textvariable=self.roi_edit_step_vars[key],
                width=5,
            ).pack(side="left")
            ttk.Label(roi_steps, text=unit).pack(side="left", padx=(1, 0))
        # The live settings in a row of their own at natural width.  Gridded
        # into columns shared with the full-width rows, the label and button
        # cells came out narrower than their text on Windows ("Apply li",
        # "Max points" without its colon).
        live_row = ttk.Frame(roi_edit)
        live_row.grid(row=2, column=0, columnspan=10, sticky="w", pady=(6, 0))
        ttk.Label(live_row, text="Live refresh (s/point):").pack(side="left")
        ttk.Spinbox(
            live_row,
            from_=0.05,
            to=3600.0,
            increment=0.1,
            textvariable=self.roi_live_interval_var,
            width=8,
        ).pack(side="left", padx=(3, 12))
        ttk.Label(live_row, text="Max points:").pack(side="left")
        ttk.Spinbox(
            live_row,
            from_=10,
            to=10000,
            increment=10,
            textvariable=self.roi_live_max_points_var,
            width=8,
        ).pack(side="left", padx=(3, 0))
        # Apply and the image buttons share the next row: beside the live
        # settings they made ROI editing too wide to sit next to the scan.
        image_buttons = ttk.Frame(roi_edit)
        image_buttons.grid(row=3, column=0, columnspan=10, pady=(6, 0), sticky="w")
        ttk.Button(
            image_buttons,
            text="Apply live settings",
            command=self.apply_roi_live_settings,
        ).pack(side="left", padx=(0, 6))
        ttk.Button(
            image_buttons,
            text="Save processed image",
            command=lambda: self.save_current_processed_image(self._keithley_page_model()),
        ).pack(side="left", padx=(0, 3))
        ttk.Button(
            image_buttons,
            text="Save raw 16-bit image",
            command=lambda: self.save_current_raw_image(self._keithley_page_model()),
        ).pack(side="left")

        video_bar = ttk.Frame(roi_edit)
        video_bar.grid(
            row=4, column=0, columnspan=10, sticky="ew", pady=(6, 0)
        )
        ttk.Label(video_bar, text="Camera Live 8-bit recording: FPS").pack(side="left")
        ttk.Entry(
            video_bar,
            textvariable=self.camera_video_fps_var,
            width=5,
        ).pack(side="left", padx=(3, 4))
        # A negative width is a minimum: wide enough for "Start recording" and
        # "Stop recording", so the text is never cut and the status beside it
        # does not move when the label changes.
        keithley_video_button = ttk.Button(
            video_bar,
            text="Start recording",
            command=self.toggle_camera_video_recording,
            state="disabled",
            width=-16,
        )
        keithley_video_button.pack(side="left")
        self.camera_video_buttons.append(keithley_video_button)
        # As for the ROI mean: a long recording status (frames, seconds and
        # dropped frames) wraps instead of widening ROI editing.
        ttk.Label(
            video_bar,
            textvariable=self.camera_video_status_var,
            style="Muted.TLabel",
            width=-36,
            wraplength=self._ui_px(290),
        ).pack(side="left", padx=(7, 0))

        self._arrange_pair_by_width(acquisition, scan, roi_edit, gap=7)

        ttk.Label(
            outer,
            text="Hold Shift and left-drag in the camera window to select an ROI; scans require difference mode.",
            foreground="#9a4d00",
        ).grid(row=3, column=0, sticky="w", pady=(0, 7))

        # The two plots in one row, equally wide.  |R| vs time moved to the
        # Non-local page.
        data_frame = ttk.Frame(outer)
        data_frame.grid(row=4, column=0, sticky="nsew")
        data_frame.rowconfigure(0, weight=1)
        for column in range(2):
            data_frame.columnconfigure(column, weight=1, uniform="moke24_plots")

        def plot_box(column: int, title: str, redraw) -> tk.Canvas:
            frame = ttk.LabelFrame(data_frame, text=title, padding=6)
            frame.grid(
                row=0, column=column, sticky="nsew",
                padx=(0 if column == 0 else 3, 0 if column == 1 else 3),
            )
            frame.rowconfigure(0, weight=1)
            frame.columnconfigure(0, weight=1)
            # A small requested width: Tk's default (about 380 px) was wider
            # than a third of the lab's 1101 px window, and the canvas was cut.
            canvas = tk.Canvas(
                frame,
                bg="#fbfcfd",
                highlightthickness=1,
                highlightbackground="#cfd6dd",
                width=self._ui_px(160, 100, canvas=True),
                height=self._ui_px(200, 120, canvas=True),
            )
            canvas.grid(row=0, column=0, sticky="nsew")
            # Also on <Map>: a <Configure> that arrives while the tab is
            # still unmapped is skipped by the plots' visibility check, which
            # left an empty plot blank until new data came.
            for sequence in ("<Configure>", "<Map>"):
                canvas.bind(sequence, lambda _event: redraw(), add="+")
            return canvas

        self.keithley_intensity_canvas = plot_box(
            0, "ROI mean intensity vs time (live)", self._redraw_live_intensity_plots
        )
        self.keithley_plot_canvas = plot_box(
            1, "Voltage vs ROI mean (voltage scan)", self._redraw_keithley_plot
        )

        ttk.Label(
            outer,
            textvariable=self.keithley_status_var,
            style="Status.TLabel",
            anchor="w",
        ).grid(row=5, column=0, sticky="ew", pady=(8, 0))
        self._update_keithley_controls()

    def build_k6221_ui(self) -> None:
        outer = ttk.Frame(self.k6221_tab, padding=7)
        outer.grid(row=0, column=0, sticky="nsew")
        outer.columnconfigure(0, weight=1)

        # Compact, as on the STFMR page: the connection beside the pulse
        # output, and the pulse scan beside ROI editing.  Each pair stacks by
        # itself when the window is too narrow for both.  (User, 2026-10-12:
        # no AC/DC continuous output on this page.)
        top = ttk.Frame(outer)
        top.grid(row=0, column=0, sticky="ew")
        top.columnconfigure(1, weight=1)
        connection = ttk.LabelFrame(top, text="Keithley 6221 / VISA", padding=7)
        connection.grid(row=0, column=0, sticky="nsew")
        connection.columnconfigure(5, weight=1)
        ttk.Label(connection, text="Resource:").grid(row=0, column=0)
        ttk.Entry(
            connection, textvariable=self.k6221_resource_var, width=18
        ).grid(row=0, column=1, padx=(0, 8))
        self.k6221_connect_button = ttk.Button(
            connection, text="Connect", command=self.connect_k6221
        )
        self.k6221_connect_button.grid(row=0, column=2, padx=3)
        self.k6221_disconnect_button = ttk.Button(
            connection, text="Disconnect", command=self.disconnect_k6221
        )
        self.k6221_disconnect_button.grid(row=0, column=3, padx=3)
        self._create_connection_indicator(connection, "keithley6221").grid(
            row=0, column=4, padx=(8, 1)
        )
        ttk.Label(connection, textvariable=self.k6221_connection_var).grid(
            row=0, column=5, sticky="e", padx=(1, 0)
        )
        ttk.Checkbutton(
            connection,
            text="6221 wiring, sample current/compliance and output parameters confirmed safe",
            variable=self.k6221_safety_var,
            command=self._update_k6221_controls,
        ).grid(
            row=1,
            column=0,
            columnspan=6,
            sticky="w",
            pady=(8, 0),
        )

        output = ttk.LabelFrame(
            top, text="DC unipolar pulse output (0 A ↔ ±I, 50% duty)", padding=7
        )
        output.grid(row=0, column=1, sticky="nsew")
        output.columnconfigure(0, weight=1)
        # The fields, then the Apply and red stop buttons on the line below
        # with the live readback, so the box is narrow enough to sit beside
        # the connection at the lab's 2000 px window (Windows fonts).
        output_fields = ttk.Frame(output)
        output_fields.grid(row=0, column=0, sticky="w")
        readback = ttk.Frame(output)
        readback.grid(row=1, column=0, sticky="ew", pady=(6, 0))
        readback.columnconfigure(5, weight=1)
        # The size of the pulse; its sign is the button's (user, 2026-10-12:
        # negative pulses), so the direction changes without retyping.
        ttk.Label(output_fields, text="Pulse current |I| (mA):").grid(row=0, column=0)
        ttk.Entry(output_fields, textvariable=self.k6221_current_var, width=9).grid(
            row=0, column=1, padx=(0, 10)
        )
        ttk.Label(output_fields, text="High-level width (us):").grid(row=0, column=2)
        ttk.Entry(output_fields, textvariable=self.k6221_width_var, width=9).grid(
            row=0, column=3, padx=(0, 10)
        )
        ttk.Label(output_fields, text="Pulse count:").grid(row=0, column=4)
        ttk.Entry(output_fields, textvariable=self.k6221_count_var, width=9).grid(
            row=0, column=5, padx=(0, 10)
        )
        ttk.Label(output_fields, text="Compliance (V):").grid(row=0, column=6)
        ttk.Entry(output_fields, textvariable=self.k6221_compliance_var, width=8).grid(
            row=0, column=7, padx=(0, 10)
        )
        self.k6221_apply_button = ttk.Button(
            readback, text="Apply +I pulse", command=lambda: self.apply_k6221_output(1)
        )
        self.k6221_apply_button.grid(row=0, column=0, padx=(0, 3))
        self.k6221_apply_negative_button = ttk.Button(
            readback, text="Apply −I pulse", command=lambda: self.apply_k6221_output(-1)
        )
        self.k6221_apply_negative_button.grid(row=0, column=1, padx=(3, 3))
        self.k6221_off_button = tk.Button(
            readback,
            text="6221 stop now / zero",
            command=self.stop_k6221,
            bg="#d70018",
            fg="white",
            activebackground="#a80012",
            activeforeground="white",
            padx=10,
            pady=3,
        )
        self.k6221_off_button.grid(row=0, column=2, padx=(8, 18))
        # The live readback (read every 0.3 s while idle): the output state
        # and whether the 6221 is in compliance; then the output set.
        ttk.Label(
            readback, textvariable=self.k6221_readback_output_var, style="Metric.TLabel"
        ).grid(row=0, column=3, sticky="w", padx=(0, 12))
        self.k6221_compliance_state_label = ttk.Label(
            readback,
            textvariable=self.k6221_compliance_state_var,
            foreground="#666666",
            font=(self.ui_font_family, self.ui_font_size, "bold"),
        )
        self.k6221_compliance_state_label.grid(row=0, column=4, sticky="w")
        ttk.Label(
            readback, textvariable=self.k6221_output_var, style="Metric.TLabel"
        ).grid(row=0, column=5, sticky="e", padx=(12, 0))
        self._arrange_pair_by_width(top, connection, output, gap=7)

        # The Avtech pulse generator (user, 2026-10-13): one pulse per button,
        # Avtech's single-pulse sequence; the output is off between pulses.
        avtech = ttk.LabelFrame(
            outer, text="Avtech AVR-E3-B pulse generator (GPIB; 50 Ω load required)", padding=7
        )
        avtech.grid(row=1, column=0, sticky="ew", pady=(7, 0))
        avtech.columnconfigure(0, weight=1)
        avtech_connection = ttk.Frame(avtech)
        avtech_connection.grid(row=0, column=0, sticky="w")
        ttk.Label(avtech_connection, text="Resource:").grid(row=0, column=0)
        ttk.Entry(avtech_connection, textvariable=self.avtech_resource_var, width=18).grid(
            row=0, column=1, padx=(0, 8)
        )
        self.avtech_connect_button = ttk.Button(
            avtech_connection, text="Connect", command=self.connect_avtech
        )
        self.avtech_connect_button.grid(row=0, column=2, padx=3)
        self.avtech_disconnect_button = ttk.Button(
            avtech_connection, text="Disconnect", command=self.disconnect_avtech
        )
        self.avtech_disconnect_button.grid(row=0, column=3, padx=3)
        self._create_connection_indicator(avtech_connection, "avtech").grid(row=0, column=4, padx=(8, 1))
        ttk.Label(avtech_connection, textvariable=self.avtech_connection_var).grid(
            row=0, column=5, sticky="w", padx=(1, 12)
        )
        ttk.Label(avtech_connection, textvariable=self.avtech_output_var, style="Metric.TLabel").grid(
            row=0, column=6, sticky="w"
        )
        avtech_pulse = ttk.Frame(avtech)
        avtech_pulse.grid(row=1, column=0, sticky="w", pady=(6, 0))
        ttk.Label(avtech_pulse, text="Amplitude |V| (V):").grid(row=0, column=0)
        ttk.Entry(avtech_pulse, textvariable=self.avtech_amplitude_var, width=8).grid(
            row=0, column=1, padx=(0, 10)
        )
        ttk.Label(avtech_pulse, text="Width (ns):").grid(row=0, column=2)
        ttk.Entry(avtech_pulse, textvariable=self.avtech_width_var, width=8).grid(
            row=0, column=3, padx=(0, 10)
        )
        self.avtech_apply_button = ttk.Button(
            avtech_pulse, text="Apply +V pulse", command=lambda: self.apply_avtech_pulse(1)
        )
        self.avtech_apply_button.grid(row=0, column=4, padx=(0, 3))
        self.avtech_apply_negative_button = ttk.Button(
            avtech_pulse, text="Apply −V pulse", command=lambda: self.apply_avtech_pulse(-1)
        )
        self.avtech_apply_negative_button.grid(row=0, column=5, padx=(3, 3))
        self.avtech_off_button = tk.Button(
            avtech_pulse,
            text="Avtech output off",
            command=self.avtech_output_off,
            bg="#d70018",
            fg="white",
            activebackground="#a80012",
            activeforeground="white",
            padx=10,
            pady=3,
        )
        self.avtech_off_button.grid(row=0, column=6, padx=(8, 0))
        ttk.Checkbutton(
            avtech,
            text="Avtech: 50 Ω load at the output (a missing load is not detected), wiring and amplitude confirmed safe",
            variable=self.avtech_safety_var,
            command=self._update_k6221_controls,  # also the scan's Start
        ).grid(row=2, column=0, sticky="w", pady=(6, 0))
        avtech_status = ttk.Label(avtech, width=1)
        avtech_status.grid(row=3, column=0, sticky="ew", pady=(2, 0))
        show_trimmed(avtech_status, self.avtech_status_var)

        # The pulse sign scan (user, 2026-10-12): Pulses pulses at the pulse
        # output's |I|, width and compliance, each with its sign from Signs,
        # and after each the raw and processed TIFFs.
        scan = ttk.LabelFrame(
            outer, text="Pulse sign scan (display, raw + processed TIFF after each pulse)", padding=7
        )
        scan.grid(row=2, column=0, sticky="ew", pady=(7, 0))
        scan.columnconfigure(11, weight=1)
        for column, (label, variable, width) in enumerate((
            ("|I| mA:", self.cidwm_scan_current_var, 7),
            ("|V| V:", self.cidwm_scan_amplitude_var, 7),
            ("Pulses:", self.cidwm_scan_pulses_var, 7),
            ("Signs:", self.cidwm_scan_signs_var, 14),
            ("Wait after pulse s:", self.cidwm_scan_wait_var, 6),
        )):
            ttk.Label(scan, text=label).grid(
                row=0, column=2 * column, sticky="e", padx=(0 if column == 0 else 10, 3)
            )
            ttk.Entry(scan, textvariable=variable, width=width).grid(
                row=0, column=2 * column + 1, sticky="w"
            )
        # The buttons on their own line, so the row fits the lab's default
        # 1101 px window with the |I| box.
        buttons = ttk.Frame(scan)
        buttons.grid(row=1, column=0, columnspan=12, sticky="w", pady=(4, 0))
        # The pulse source (user, 2026-10-13): the 6221 (|I| mA, its pulse
        # output's width and compliance) or the Avtech (|V| V, its width).
        ttk.Label(buttons, text="Pulse source:").grid(row=0, column=0, padx=(0, 3))
        self.cidwm_scan_source_buttons = []
        for column, (value, text) in enumerate((("6221", "6221"), ("avtech", "Avtech")), 1):
            button = ttk.Radiobutton(
                buttons, text=text, value=value, variable=self.cidwm_scan_source_var,
                command=self._update_k6221_controls,
            )
            button.grid(row=0, column=column, padx=(0, 6))
            self.cidwm_scan_source_buttons.append(button)
        self.cidwm_scan_start_button = ttk.Button(
            buttons, text="Choose folder and start scan", command=self.start_cidwm_pulse_scan
        )
        self.cidwm_scan_start_button.grid(row=0, column=3, padx=(10, 3))
        self.cidwm_scan_stop_button = ttk.Button(
            buttons, text="Stop", command=self.stop_cidwm_pulse_scan, state="disabled"
        )
        self.cidwm_scan_stop_button.grid(row=0, column=4, padx=(3, 0))
        ttk.Label(
            scan,
            text="Signs: + and - per pulse, repeated to fill Pulses (+- alternates, ++-- goes in pairs)",
            style="Muted.TLabel",
        ).grid(row=2, column=0, columnspan=12, sticky="w", pady=(4, 0))
        ttk.Label(
            scan,
            text="6221: |I| mA, width and compliance from its pulse output; Avtech: |V| V, width from its box",
            style="Muted.TLabel",
        ).grid(row=3, column=0, columnspan=12, sticky="w")
        scan_status = ttk.Label(scan, width=1)
        scan_status.grid(row=4, column=0, columnspan=12, sticky="ew", pady=(2, 0))
        show_trimmed(scan_status, self.cidwm_scan_status_var)

        # CIDWM: under the pulse sign scan, the MOKE magnet page's
        # difference display beside one Save images button, then its display
        # rows as "Camera settings" (user, 2026-10-12: no ROI editing, no live
        # ROI plot).  They share the camera settings with MOKE magnet.
        moke = ttk.Frame(outer)
        moke.grid(row=3, column=0, sticky="ew", pady=(7, 3))
        # The Images box keeps its natural width and the difference display
        # takes the rest, as on MOKE magnet, so the display's width never
        # depends on its own mode row's layout (2026-10-12: with the spare
        # width on the Images side, that row flipped between side by side
        # and stacked forever and the program hung at start-up).
        moke.columnconfigure(0, weight=1)
        difference_box = self._build_moke_difference_box(moke)
        difference_box.grid(row=0, column=0, sticky="nsew")
        images = ttk.LabelFrame(moke, text="Images", padding=7)
        images.grid(row=0, column=1, sticky="nsew")
        self.cidwm_save_images_button = ttk.Button(
            images, text="Save images", command=self.save_cidwm_images
        )
        self.cidwm_save_images_button.grid(row=0, column=0, sticky="w")
        ttk.Label(
            images,
            text="The current display (8-bit PNG), the raw 16-bit TIFF and the "
                 "difference raw image (float32 TIFF), into the folder you choose",
            style="Muted.TLabel",
        ).grid(row=1, column=0, sticky="w", pady=(4, 0))
        self._arrange_pair_by_width(moke, difference_box, images, gap=7)
        # The display rows in one box (user, 2026-10-12: "Camera settings").
        camera_settings = ttk.LabelFrame(outer, text="Camera settings", padding=4)
        camera_settings.grid(row=4, column=0, sticky="ew", pady=(0, 4))
        camera_settings.columnconfigure(0, weight=1)
        self._build_moke_display_controls(camera_settings).grid(row=0, column=0, sticky="ew")
        # Spare height below the controls, so the status line stays at the
        # bottom of the page.
        outer.rowconfigure(5, weight=1)
        ttk.Label(
            outer,
            textvariable=self.k6221_status_var,
            style="Status.TLabel",
            anchor="w",
        ).grid(row=6, column=0, sticky="ew", pady=(7, 0))
        self._update_k6221_controls()

    def build_nonlocal_vi_ui(self) -> None:
        """Build the Non-local page: one instrument rack, then the Gate-VI
        pulse scan (Keithley 2410/2400 pulse -> 6221/SR830 VI), |R| vs time
        and the I-V sweep on sub-tabs, all on the same Keithley."""
        outer = ttk.Frame(self.nonlocal_vi_tab, padding=7)
        outer.grid(row=0, column=0, sticky="nsew")
        outer.columnconfigure(0, weight=1)
        outer.rowconfigure(1, weight=1)

        connection = ttk.LabelFrame(
            outer,
            text="Non-local instrument connections",
            padding=7,
        )
        connection.grid(row=0, column=0, sticky="ew")
        # Two columns, as on the PPMS page: the Keithleys on the left, the
        # lock-ins on the right, side by side when both fit, else stacked.
        # Only connections here (and the Keithley model), each row with its
        # own state; the pulse scan's read settings are with its parameters,
        # as on the STFMR page.  Each column's grid holds a device's name,
        # address, Connect, Disconnect, lamp and status.
        sources = ttk.Frame(connection)
        meters = ttk.Frame(connection)
        sources.grid(row=0, column=0, sticky="nw")
        meters.grid(row=0, column=1, sticky="nw")

        def indicator(frame, key: str, row: int, column: int) -> None:
            canvas = tk.Canvas(
                frame,
                width=16,
                height=16,
                highlightthickness=0,
                background=self.root.cget("background"),
            )
            item = canvas.create_oval(
                3, 3, 13, 13, fill="#9aa0a6", outline="#6f757b"
            )
            canvas.grid(
                row=row, column=column, padx=(1, 4), pady=(4 if row else 0, 0)
            )
            self.nonlocal_vi_connection_indicators[key] = (canvas, item)

        def device_name(frame, row: int, **label) -> None:
            # Right-aligned in a fixed width, as on the STFMR and PPMS rows,
            # so every address field starts at the same place.
            ttk.Label(frame, width=15, anchor="e", **label).grid(
                row=row, column=0, sticky="e", pady=(4 if row else 0, 0)
            )

        def device_address(frame, row: int, variable) -> None:
            ttk.Entry(frame, textvariable=variable, width=18).grid(
                row=row, column=1, padx=(0, 12), pady=(4 if row else 0, 0),
                sticky="w",
            )

        def device_actions(frame, key: str, row: int) -> None:
            # The STFMR and PPMS button widths.
            self.nonlocal_vi_device_connect_buttons[key] = ttk.Button(
                frame,
                text="Connect",
                width=8,
                command=lambda device_key=key:
                    self.connect_nonlocal_vi_device(device_key),
            )
            self.nonlocal_vi_device_connect_buttons[key].grid(
                row=row, column=2, padx=(4, 2), pady=(4 if row else 0, 0)
            )
            self.nonlocal_vi_device_disconnect_buttons[key] = ttk.Button(
                frame,
                text="Disconnect",
                width=10,
                command=lambda device_key=key:
                    self.disconnect_nonlocal_vi_device(device_key),
            )
            self.nonlocal_vi_device_disconnect_buttons[key].grid(
                row=row, column=3, padx=2, pady=(4 if row else 0, 0)
            )
            indicator(frame, key, row, 4)
            # As wide as the longest state, "Disconnecting…".
            ttk.Label(
                frame,
                textvariable=self.nonlocal_vi_device_connection_vars[key],
                width=14,
                anchor="w",
            ).grid(row=row, column=5, pady=(4 if row else 0, 0), sticky="w")

        device_name(sources, 0, textvariable=self.nonlocal_vi_keithley_label_var)
        device_address(sources, 0, self.nonlocal_vi_2410_resource_var)
        device_actions(sources, "2410", 0)
        # Which SourceMeter: 2410 or 2400, fixed while connected.  It is
        # driven the same way on this page (20 V range and OVP, 1 mA).
        model_box = ttk.Frame(sources)
        model_box.grid(row=0, column=6, sticky="w", padx=(12, 0))
        ttk.Label(model_box, text="Model:").grid(
            row=0, column=0, sticky="e", padx=(0, 3)
        )
        self.nonlocal_vi_model_combo = ttk.Combobox(
            model_box,
            textvariable=self.nonlocal_vi_2410_model_var,
            values=tuple(KEITHLEY_MODELS),
            state="readonly",
            width=5,
        )
        self.nonlocal_vi_model_combo.grid(row=0, column=1, sticky="ew")
        self.nonlocal_vi_model_combo.bind(
            "<<ComboboxSelected>>", lambda _event: self._on_nonlocal_vi_model_selected()
        )
        device_name(sources, 1, text="Keithley 6221:")
        device_address(sources, 1, self.nonlocal_vi_source_resource_var)
        device_actions(sources, "6221", 1)
        device_name(sources, 2, text="Keithley 2182A:")
        device_address(sources, 2, self.nonlocal_vi_nanovoltmeter_resource_var)
        device_actions(sources, "2182", 2)

        for row, key in ((0, "8"), (1, "9")):
            device_name(meters, row, text=f"SR830 #{key}:")
            device_address(meters, row, self.nonlocal_vi_lockin_resource_vars[key])
            device_actions(meters, key, row)
        device_name(meters, 2, text="Zurich MFLI:")
        # Which Zurich: chosen from the lab's two, so the Data Server that can
        # reach it is used.  As wide as the SR830 address fields above.
        vi_mfli_chooser = create_zurich_chooser(
            meters, self.nonlocal_vi_mfli_device_var, match_chars=18
        )
        self.nonlocal_vi_mfli_chooser = vi_mfli_chooser
        vi_mfli_chooser.grid(
            row=2, column=1, padx=(0, 12 + vi_mfli_chooser.zurich_shortfall),
            pady=(4, 0), sticky="w",
        )
        device_actions(meters, "mfli", 2)
        # As the RT-E rack's Zurich row: its reference input and time
        # constant, used by the Gate-VI and 6221-IV scans.
        ttk.Label(meters, text="Ref.").grid(row=2, column=6, padx=(8, 3), pady=(4, 0))
        reference_combo = ttk.Combobox(
            meters,
            textvariable=self.nonlocal_vi_mfli_reference_source_var,
            values=tuple(NONLOCAL_MFLI_REFERENCE_INPUTS),
            state="readonly",
            width=12,
        )
        reference_combo.grid(row=2, column=7, pady=(4, 0))
        self.nonlocal_mfli_reference_combo = reference_combo
        # A change is applied to a connected Zurich at once, as on RT-E.
        reference_combo.bind(
            "<<ComboboxSelected>>", lambda _event: self._apply_nonlocal_mfli_settings(), add="+"
        )
        ttk.Label(meters, text="TC (s)").grid(row=2, column=8, padx=(8, 3), pady=(4, 0))
        tc_entry = ttk.Entry(meters, textvariable=self.nonlocal_mfli_tc_var, width=6)
        tc_entry.grid(row=2, column=9, pady=(4, 0))
        self.nonlocal_mfli_tc_entry = tc_entry
        for sequence in ("<Return>", "<FocusOut>"):
            tc_entry.bind(sequence, lambda _event: self._apply_nonlocal_mfli_settings(tc_edit=True), add="+")
        self.nonlocal_mfli_after_id = self.root.after(NONLOCAL_MFLI_POLL_MS, self._poll_nonlocal_mfli)
        # Stacked in a narrow window, the lock-ins follow the Keithleys at the
        # same row spacing, one list as on the STFMR page.
        self._arrange_pair_by_width(connection, sources, meters, gap=24, stack_gap=4)

        def wrap_to_width(label) -> None:
            """Wrap a label's text at its current width, re-done on resize."""
            label.bind(
                "<Configure>",
                lambda event: event.widget.configure(
                    wraplength=max(100, event.width - 8)
                ),
                add="+",
            )

        # The measurements share the rack above.  Gate-VI keeps its layout on
        # the first sub-tab; |R| vs time (from MOKE-24) and the I-V sweep use
        # the Keithley alone.  In the lab's 1101 px window the rack takes
        # about half the height, so only the sub-tab strip comes between it
        # and the measurement.
        self.nonlocal_measurements = ttk.Notebook(outer)
        self.nonlocal_measurements.grid(row=1, column=0, sticky="nsew", pady=(5, 0))
        gate_tab = ttk.Frame(self.nonlocal_measurements, padding=(0, 5, 0, 0))
        resistance_tab = ttk.Frame(self.nonlocal_measurements, padding=(0, 5, 0, 0))
        iv_tab = ttk.Frame(self.nonlocal_measurements, padding=(0, 5, 0, 0))
        iv6221_tab = ttk.Frame(self.nonlocal_measurements, padding=(0, 5, 0, 0))
        # In the user's order (2026-10-08): |R| vs time, 2400-IV (the
        # Keithley I-V sweep), 6221-IV (the RT-E Current scan), Gate-VI scan.
        self.nonlocal_measurements.add(resistance_tab, text="|R| vs time")
        self.nonlocal_measurements.add(iv_tab, text="2400-IV")
        self.nonlocal_measurements.add(iv6221_tab, text="6221-IV")
        self.nonlocal_measurements.add(gate_tab, text="Gate-VI scan")
        self.nonlocal_measurements.bind(
            "<<NotebookTabChanged>>",
            lambda _event: (
                self._redraw_nonlocal_vi_plots(),
                self._redraw_nonlocal_resistance_plot(),
                self._redraw_nonlocal_iv_plot(),
                self._redraw_nonlocal_iv6221_plots(),
            ),
            add="+",
        )
        # The red stop button at the right end of the sub-tab strip, so it
        # shows on every sub-tab; it stops whichever measurement holds the
        # Keithley or the 6221.
        self.nonlocal_vi_off_button = tk.Button(
            outer,
            text=f"Stop {NONLOCAL_DEFAULT_KEITHLEY_MODEL} / 6221 now",
            command=self.stop_nonlocal_vi,
            bg="#d70018",
            fg="white",
            activebackground="#a80012",
            activeforeground="white",
            padx=12,
            pady=1,
        )
        self.nonlocal_vi_off_button.grid(row=1, column=0, sticky="ne", pady=(5, 0))
        self.nonlocal_vi_off_button.lift()
        gate_tab.columnconfigure(0, weight=1)
        gate_tab.rowconfigure(2, weight=1)

        # The pulse scan's interlock (kept word for word), wrapped to the
        # page width.  Names the selected model; set in
        # _refresh_nonlocal_vi_model_labels.
        interlock = ttk.Label(
            gate_tab,
            textvariable=self.nonlocal_vi_interlock_var,
            foreground="#a34b00",
        )
        interlock.grid(row=0, column=0, sticky="ew", padx=2, pady=(0, 5))
        wrap_to_width(interlock)

        # As on the RT-E page: the instruments' own settings in one box and
        # the scan in another, side by side when both fit, else stacked.
        controls = ttk.Frame(gate_tab)
        controls.grid(row=1, column=0, sticky="ew", pady=(0, 5))
        controls.columnconfigure(1, weight=1)
        settings = ttk.LabelFrame(controls, text="Gate-VI settings", padding=6)
        settings.grid(row=0, column=0, sticky="nsew")
        scan = ttk.LabelFrame(controls, text="Gate-VI scan", padding=6)
        scan.grid(row=0, column=1, sticky="nsew", padx=(6, 0))

        # Settings, laid out as "6221-IV settings": the safety tick and the
        # 6221 on the left, one row per voltmeter on the right.
        settings.columnconfigure(0, weight=1)
        self._build_nonlocal_vi_read_settings(settings).grid(row=0, column=0, sticky="new")

        # Scan: the pulse sweep and the read per point, three to a row.
        for index, (label, variable) in enumerate((
            ("Start V", self.nonlocal_vi_start_voltage_var),
            ("Stop V", self.nonlocal_vi_stop_voltage_var),
            ("Step V", self.nonlocal_vi_step_voltage_var),
            ("Pulse width s", self.nonlocal_vi_pulse_width_var),
            ("Post-pulse wait s", self.nonlocal_vi_post_pulse_var),
            ("Pulse gate MΩ", self.nonlocal_vi_gate_resistance_var),
            ("Sample Hz", self.nonlocal_vi_sample_hz_var),
            ("6221 pre-run s", self.nonlocal_vi_settle_var),
            ("Measure/pt s", self.nonlocal_vi_measure_var),
        )):
            row, slot = divmod(index, 3)
            ttk.Label(scan, text=f"{label}:").grid(
                row=row, column=2 * slot, sticky="e", padx=(0 if slot == 0 else 10, 3), pady=2
            )
            ttk.Entry(scan, textvariable=variable, width=8).grid(
                row=row, column=2 * slot + 1, sticky="w", pady=2
            )
        # Loops (user, 2026-10-11), then the frequency scan, on one row.
        ttk.Label(scan, text="Loops:").grid(row=3, column=0, sticky="e", padx=(0, 3), pady=2)
        ttk.Entry(scan, textvariable=self.nonlocal_vi_loops_var, width=8).grid(
            row=3, column=1, sticky="w", pady=2
        )
        fscan, self.nonlocal_vi_fscan_widgets = self._build_nonlocal_fscan_row(scan, "nonlocal_vi")
        # Into the box's spare width (column 6), so its note is not cut short.
        scan.columnconfigure(6, weight=1)
        fscan.grid(row=3, column=2, columnspan=5, sticky="ew", padx=(10, 0), pady=2)
        actions = ttk.Frame(scan)
        actions.grid(row=4, column=0, columnspan=6, sticky="ew", pady=(6, 0))
        actions.columnconfigure(2, weight=1)
        self.nonlocal_vi_start_button = ttk.Button(
            actions,
            text="Choose folder and start scan",
            command=self.start_nonlocal_vi_scan,
        )
        self.nonlocal_vi_start_button.grid(row=0, column=0, padx=(0, 4))
        self.nonlocal_vi_stop_button = ttk.Button(
            actions, text="Stop scan", command=self.stop_nonlocal_vi
        )
        self.nonlocal_vi_stop_button.grid(row=0, column=1, padx=(0, 8))
        self.nonlocal_vi_progress = ttk.Progressbar(
            actions, mode="determinate", maximum=1, value=0, length=120
        )
        self.nonlocal_vi_progress.grid(row=0, column=2, sticky="ew", padx=(0, 8))
        ttk.Label(
            actions,
            textvariable=self.nonlocal_vi_eta_var,
            style="Success.TLabel",
            width=20,
            anchor="w",
        ).grid(row=0, column=3, sticky="e")
        # The readouts, each a fixed-width box so a new value never moves the
        # others; the lock-in reference text wraps rather than pushing
        # anything off.
        readouts = ttk.Frame(scan)
        readouts.grid(row=5, column=0, columnspan=6, sticky="ew", pady=(5, 0))
        readouts.columnconfigure(2, weight=1)
        ttk.Label(
            readouts,
            textvariable=self.nonlocal_vi_output_var,
            style="Metric.TLabel",
            width=44,
            anchor="w",
        ).grid(row=0, column=0, columnspan=3, sticky="nw")
        mfli_lock_readout = ttk.Label(
            readouts,
            textvariable=self.nonlocal_vi_mfli_lock_var,
            style="Metric.TLabel",
            width=22,
            anchor="w",
        )
        # One text line tall with the dot centred.
        try:
            lamp_height = max(16, int(mfli_lock_readout.winfo_reqheight()))
        except (tk.TclError, TypeError, ValueError, AttributeError):
            lamp_height = 16
        vi_mfli_lock_canvas = tk.Canvas(
            readouts,
            width=16,
            height=lamp_height,
            highlightthickness=0,
            background=self.root.cget("background"),
        )
        lamp_middle = lamp_height // 2
        vi_mfli_lock_item = vi_mfli_lock_canvas.create_oval(
            3, lamp_middle - 5, 13, lamp_middle + 5,
            fill="#9aa0a6", outline="#6f757b",
        )
        vi_mfli_lock_canvas.grid(row=1, column=0, sticky="nw", padx=(0, 3), pady=(3, 0))
        self.nonlocal_vi_mfli_lock_indicator = (
            vi_mfli_lock_canvas, vi_mfli_lock_item
        )
        mfli_lock_readout.grid(row=1, column=1, sticky="nw", padx=(0, 12), pady=(3, 0))
        reference_readout = ttk.Label(
            readouts,
            textvariable=self.nonlocal_vi_reference_var,
            style="Metric.TLabel",
            anchor="w",
            justify="left",
            width=1,
        )
        reference_readout.grid(row=1, column=2, sticky="new", pady=(3, 0))
        wrap_to_width(reference_readout)
        self._arrange_pair_by_width(controls, settings, scan, gap=6, stack_gap=4)
        self._keep_pair_left_room(controls, settings, scan, gap=6)

        plots = ttk.Frame(gate_tab)
        self.nonlocal_vi_plot_container = plots
        plots.grid(row=2, column=0, sticky="nsew")
        for column in range(3):
            plots.columnconfigure(column, weight=1, uniform="nonlocal_vi_plots")
        # User, 2026-10-09: first the lock-ins' X, Y and θ against time, a
        # row per harmonic order measured, as on 6221-IV (every meter ticked
        # Measure overlaid, the 2182A's voltage with X in the top row); then
        # the Keithley's resistance and the voltage against the pulse
        # voltage, one plot per order (user, 2026-10-09: no command-voltage
        # plot).  _layout_nonlocal_vi_plots shows the orders measured.

        def add_plot(frame, key):
            canvas = self._nonlocal_plot_canvas(frame, self._redraw_nonlocal_vi_plots)
            canvas.configure(height=PPMS_PLOT_ROW_MIN_HEIGHT_PX)
            # The legend above the plot, clear of the curves.
            canvas.ppms_compact_plot = True
            self.nonlocal_vi_plot_frames[key] = frame
            self.nonlocal_vi_plot_canvases[key] = canvas

        for order in PPMS_HARMONIC_ORDERS:
            for column, (channel, title) in enumerate((("x", "X"), ("y", "Y"), ("theta", "θ"))):
                frame = ttk.LabelFrame(
                    plots, text=f"{PPMS_HARMONIC_LABELS[order]} {title} vs time", padding=2
                )
                frame.grid(
                    row=order - 1, column=column, sticky="nsew",
                    padx=(0 if column == 0 else 3, 0 if column == 2 else 3), pady=(0, 3),
                )
                add_plot(frame, (order, channel))
        bottom = ttk.Frame(plots)
        bottom.grid(
            row=len(PPMS_HARMONIC_ORDERS), column=0, columnspan=3, sticky="nsew", pady=(3, 0)
        )
        plots.rowconfigure(len(PPMS_HARMONIC_ORDERS), weight=1)
        bottom.rowconfigure(0, weight=1)
        self.nonlocal_vi_bottom_plots = bottom
        for key, title in (
            ("resistance", f"Keithley {NONLOCAL_DEFAULT_KEITHLEY_MODEL} resistance"),
            *((("summary", order),
               f"{PPMS_HARMONIC_LABELS[order]} {NONLOCAL_VI_SUMMARY_CHANNELS[order]} vs pulse voltage")
              for order in PPMS_HARMONIC_ORDERS),
        ):
            add_plot(ttk.LabelFrame(bottom, text=title, padding=2), key)
        self.nonlocal_vi_plot_orders = None

        self._build_nonlocal_resistance_tab(resistance_tab)
        self._build_nonlocal_iv_tab(iv_tab)
        self._build_nonlocal_iv6221_tab(iv6221_tab)

        ttk.Label(
            outer,
            textvariable=self.nonlocal_vi_status_var,
            style="Status.TLabel",
            anchor="w",
        ).grid(row=2, column=0, sticky="ew", pady=(5, 0))
        self._redraw_nonlocal_vi_plots()
        self._update_nonlocal_vi_controls()

    def _build_nonlocal_vi_read_settings(self, parent) -> ttk.Frame:
        """The pulse scan's settings, laid out as "6221-IV settings" (user,
        2026-10-09): the safety tick and the 6221 on the left; on the right
        one row per lock-in (harmonic, Measure, autorange), then the Zurich
        input and the 2182A.  Every lock-in reads AC-coupled; the voltage
        against the pulse voltage is its R (user, 2026-10-09: no Read or
        Coupling choice).  Side by side when both fit, else stacked."""
        body = ttk.Frame(parent)
        params = ttk.Frame(body)
        params.grid(row=0, column=0, sticky="nsw")
        meters = ttk.Frame(body)
        meters.grid(row=0, column=1, sticky="nsw")

        ttk.Checkbutton(
            params,
            text="Safety confirmed: voltage pulses, read current, wiring, sample",
            variable=self.nonlocal_vi_safety_var,
            command=self._update_nonlocal_vi_controls,
        ).grid(row=0, column=0, columnspan=6, sticky="w")

        def entry_at(row, column, label, variable):
            ttk.Label(params, text=label).grid(
                row=row, column=column, sticky="e", padx=(0 if column == 0 else 8, 3), pady=2
            )
            entry = ttk.Entry(params, textvariable=variable, width=5)
            entry.grid(row=row, column=column + 1, sticky="ew", pady=2)
            return entry

        # The read current is RMS with an AC output and DC with a DC one.
        entry_at(1, 0, "6221 mA", self.nonlocal_vi_current_var)
        self.nonlocal_vi_frequency_entry = entry_at(1, 2, "Frequency Hz", self.nonlocal_vi_frequency_var)
        entry_at(1, 4, "Compliance V", self.nonlocal_vi_compliance_var)
        entry_at(2, 0, "Trigger line", self.nonlocal_vi_marker_line_var)
        ttk.Label(params, text="Output").grid(row=2, column=2, sticky="e", padx=(8, 3), pady=2)
        self.nonlocal_vi_output_mode_combo = ttk.Combobox(
            params,
            textvariable=self.nonlocal_vi_output_mode_var,
            values=("AC", "DC"),
            state="readonly",
            width=4,
        )
        self.nonlocal_vi_output_mode_combo.grid(row=2, column=3, sticky="ew", pady=2)
        self.nonlocal_vi_output_mode_var.trace_add(
            "write", lambda *_args: self._on_nonlocal_vi_output_mode_changed()
        )

        # One row per lock-in, as on 6221-IV: harmonic, Measure and the
        # autorange.  The input is AC-coupled and the voltage read is R
        # (the coupling and channel variables keep those defaults).  An
        # SR830 offers 1+2 (read one after the other), the Zurich 1+2 and
        # 1+2+3 (read at once), user 2026-10-09.
        self.nonlocal_vi_harmonic_combos = []
        self.nonlocal_vi_measure_ticks = []
        for row, (key, harmonic, choices, measure) in enumerate((
            ("8", self.nonlocal_vi_lockin_harmonic_vars["8"], NONLOCAL_VI_SR830_HARMONIC_CHOICES,
             self.nonlocal_vi_measurement_enabled_vars["8"]),
            ("9", self.nonlocal_vi_lockin_harmonic_vars["9"], NONLOCAL_VI_SR830_HARMONIC_CHOICES,
             self.nonlocal_vi_measurement_enabled_vars["9"]),
            ("mfli", self.nonlocal_vi_mfli_harmonic_var, NONLOCAL_VI_ZURICH_HARMONIC_CHOICES,
             self.nonlocal_vi_use_mfli_var),
        )):
            ttk.Label(meters, text=f"{NONLOCAL_METER_NAMES[key]} harmonic").grid(
                row=row, column=0, sticky="e", padx=(12, 3), pady=2
            )
            combo = ttk.Combobox(
                meters, textvariable=harmonic, values=choices, width=6, state="readonly",
            )
            combo.grid(row=row, column=1, sticky="ew", pady=2)
            combo.bind(
                "<<ComboboxSelected>>", lambda _event: self._redraw_nonlocal_vi_plots(), add="+",
            )
            self.nonlocal_vi_harmonic_combos.append(combo)
            tick = ttk.Checkbutton(
                meters, text="Measure", variable=measure, command=self._redraw_nonlocal_vi_plots,
            )
            tick.grid(row=row, column=6, padx=(6, 3))
            # Held while a scan runs: its plots and CSV follow the meters it
            # started with (review, 2026-10-09).
            self.nonlocal_vi_measure_ticks.append(tick)
            # Narrow enough for this box to sit beside "Gate-VI scan" at 2000 px.
            ttk.Label(
                meters, width=12,
                **({"textvariable": self.nonlocal_iv6221_zurich_range_var} if key == "mfli"
                   else {"text": "Autorange ON"}),
            ).grid(row=row, column=7, sticky="w", padx=(6, 0))
        # The Zurich's Signal Input 1 is 10 MΩ, scaling 1, as on 6221-IV (user,
        # 2026-10-09: no Zurich input row); its reference input and TC are on
        # the rack's Zurich row.  Then the 2182A.
        ttk.Label(meters, text="2182A").grid(row=3, column=0, sticky="e", padx=(12, 3), pady=2)
        tick = ttk.Checkbutton(
            meters, text="Measure (channel 1, NPLC 1, autorange)",
            variable=self.nonlocal_vi_use_2182_var,
            command=self._redraw_nonlocal_vi_plots,
        )
        tick.grid(row=3, column=1, columnspan=7, sticky="w", pady=2)
        self.nonlocal_vi_measure_ticks.append(tick)
        self._arrange_pair_by_width(body, params, meters, gap=0, stack_gap=4)
        return body

    def _build_nonlocal_fscan_row(self, parent, prefix: str):
        """The frequency scan row of 6221-IV and Gate-VI (user, 2026-10-10):
        the tick, f start and f stop in Hz, and how many primes they give.
        Returns the row and its tick and entries."""
        tick_var = getattr(self, f"{prefix}_fscan_var")
        start_var = getattr(self, f"{prefix}_fstart_var")
        stop_var = getattr(self, f"{prefix}_fstop_var")
        info_var = getattr(self, f"{prefix}_fscan_info_var")
        row = ttk.Frame(parent)
        row.columnconfigure(5, weight=1)
        tick = ttk.Checkbutton(row, text="Frequency scan", variable=tick_var)
        tick.grid(row=0, column=0, sticky="w")
        widgets = [tick]
        for column, label, variable in ((1, "f start Hz", start_var), (3, "f stop Hz", stop_var)):
            ttk.Label(row, text=label).grid(row=0, column=column, sticky="e", padx=(8, 3))
            entry = ttk.Entry(row, textvariable=variable, width=6)
            entry.grid(row=0, column=column + 1, sticky="w")
            widgets.append(entry)
        info = ttk.Label(row, width=1)
        info.grid(row=0, column=5, sticky="ew", padx=(8, 0))
        show_trimmed(info, info_var)

        def refresh(*_args) -> None:
            try:
                scanning = bool(tick_var.get())
            except tk.TclError:
                scanning = False
            info_var.set(
                nonlocal_frequency_scan_text(start_var.get(), stop_var.get()) if scanning
                else "Off: Frequency Hz only"
            )

        for variable in (tick_var, start_var, stop_var):
            variable.trace_add("write", refresh)
        refresh()
        return row, widgets

    def _build_nonlocal_iv6221_tab(self, tab) -> None:
        """6221-IV as the RT-E page: "6221-IV settings" (the 6221 and each
        lock-in's harmonic and Measure tick) beside "6221-IV scan", then one
        X / Y / θ row per measured harmonic order, meters overlaid."""
        tab.columnconfigure(0, weight=1)
        tab.rowconfigure(1, weight=1)
        controls = ttk.Frame(tab)
        controls.grid(row=0, column=0, sticky="ew", pady=(0, 4))
        controls.columnconfigure(1, weight=1)
        settings = ttk.LabelFrame(controls, text="6221-IV settings", padding=4)
        settings.grid(row=0, column=0, sticky="nsew")
        settings.columnconfigure(0, weight=1)
        # The source settings on the left, the lock-in choices on the right,
        # stacked when the box is narrower than both, as on RT-E.
        body = ttk.Frame(settings)
        body.grid(row=0, column=0, sticky="new")
        params = ttk.Frame(body)
        params.grid(row=0, column=0, sticky="nsw")
        lockins = ttk.Frame(body)
        lockins.grid(row=0, column=1, sticky="nsw")
        ttk.Checkbutton(
            params,
            text="Safety confirmed: 6221 current, compliance, wiring, sample",
            variable=self.nonlocal_iv6221_safety_var,
            command=self._update_nonlocal_vi_controls,
        ).grid(row=0, column=0, columnspan=7, sticky="w")

        def entry_at(row, column, label, variable):
            ttk.Label(params, text=label).grid(
                row=row, column=column, sticky="e", padx=(0 if column == 0 else 8, 3), pady=2
            )
            ttk.Entry(params, textvariable=variable, width=6).grid(
                row=row, column=column + 1, sticky="ew", pady=2
            )

        entry_at(1, 0, "6221 mA RMS", self.nonlocal_iv6221_current_var)
        entry_at(1, 2, "Frequency Hz", self.nonlocal_iv6221_frequency_var)
        entry_at(1, 4, "Compliance V", self.nonlocal_iv6221_compliance_var)
        self.nonlocal_iv6221_set_button = ttk.Button(
            params, text="Set 6221", width=11, command=self.set_nonlocal_iv6221_current
        )
        self.nonlocal_iv6221_set_button.grid(row=1, column=6, padx=4)
        entry_at(2, 0, "Trigger line", self.nonlocal_vi_marker_line_var)
        source = ttk.Label(params, width=1)
        source.grid(row=3, column=0, columnspan=5, sticky="ew", pady=(2, 0))
        show_trimmed(source, self.nonlocal_iv6221_source_var)
        self.nonlocal_iv6221_off_button = ttk.Button(
            params, text="6221 / 2400 OFF", width=15, command=self.stop_nonlocal_vi
        )
        self.nonlocal_iv6221_off_button.grid(row=3, column=5, columnspan=2, sticky="e", padx=4)
        # The lock-in choices, held while a measurement runs (its plots and
        # CSV follow the choices it started with).
        self.nonlocal_iv6221_choice_widgets = []
        for row, key in enumerate(("8", "9", "mfli")):
            ttk.Label(lockins, text=f"{NONLOCAL_METER_NAMES[key]} harmonic").grid(
                row=row, column=0, sticky="e", padx=(12, 3), pady=2
            )
            combo = ttk.Combobox(
                lockins, textvariable=self.nonlocal_iv6221_harmonic_vars[key],
                values=tuple(PPMS_ZURICH_MODE_ORDERS), width=7, state="readonly",
            )
            combo.grid(row=row, column=1, sticky="ew", pady=2)
            self.nonlocal_iv6221_choice_widgets.append((combo, "readonly"))
            combo.bind(
                "<<ComboboxSelected>>",
                lambda _event: self._refresh_nonlocal_iv6221_plot_layout(), add="+",
            )
            if key == "mfli":
                # Applied to a connected Zurich at once, as on RT-E.
                combo.bind(
                    "<<ComboboxSelected>>",
                    lambda _event: self._apply_nonlocal_mfli_settings(), add="+",
                )
            measure = ttk.Checkbutton(
                lockins, text="Measure", variable=self.nonlocal_iv6221_measure_vars[key],
                command=self._refresh_nonlocal_iv6221_plot_layout,
            )
            measure.grid(row=row, column=2, padx=3)
            self.nonlocal_iv6221_choice_widgets.append((measure, "normal"))
            ttk.Label(
                lockins, width=14,
                **({"textvariable": self.nonlocal_iv6221_zurich_range_var} if key == "mfli"
                   else {"text": "Autorange ON"}),
            ).grid(row=row, column=3, sticky="w", padx=(6, 0))

        scan = ttk.LabelFrame(controls, text="6221-IV scan", padding=4)
        scan.grid(row=0, column=1, sticky="nsew", padx=(6, 0))
        # Spare width goes to the empty column after the table.
        scan.columnconfigure(7, weight=1)
        ttk.Label(scan, text="Current").grid(row=0, column=0)
        ttk.Label(scan, text="6221 mA RMS").grid(row=1, column=0)
        for index, (label, variable) in enumerate(zip(
            ("Start", "End", "Step", "Loops", "Settle s", "Acquire s"),
            (self.nonlocal_iv6221_start_var, self.nonlocal_iv6221_end_var,
             self.nonlocal_iv6221_step_var, self.nonlocal_iv6221_loops_var,
             self.nonlocal_iv6221_settle_var, self.nonlocal_iv6221_acquire_var),
        )):
            row, column = divmod(index, 3)
            ttk.Label(scan, text=label).grid(row=row, column=1 + 2 * column, sticky="e", padx=(6, 0))
            ttk.Entry(scan, textvariable=variable, width=6).grid(
                row=row, column=2 + 2 * column, padx=2, pady=2, sticky="ew"
            )
        fscan, self.nonlocal_iv6221_fscan_widgets = self._build_nonlocal_fscan_row(scan, "nonlocal_iv6221")
        fscan.grid(row=2, column=0, columnspan=8, sticky="ew", pady=2)
        # Held while a measurement runs, as the lock-in choices (its list is fixed then).
        self.nonlocal_iv6221_choice_widgets.extend(
            (widget, "normal") for widget in self.nonlocal_iv6221_fscan_widgets
        )
        self.nonlocal_iv6221_start_button = ttk.Button(
            scan, text="Choose folder and start scan", command=self.start_nonlocal_iv6221
        )
        self.nonlocal_iv6221_start_button.grid(row=3, column=0, columnspan=3, sticky="ew", pady=(4, 0))
        self.nonlocal_iv6221_stop_button = ttk.Button(
            scan, text="Stop", command=self.stop_nonlocal_keithley_task, state="disabled"
        )
        self.nonlocal_iv6221_stop_button.grid(row=3, column=3, columnspan=2, sticky="ew", pady=(4, 0))
        ttk.Checkbutton(
            scan, text="Round trip", variable=self.nonlocal_iv6221_round_trip_var
        ).grid(row=3, column=5, columnspan=2, pady=(4, 0))
        status = ttk.Frame(scan)
        status.grid(row=4, column=0, columnspan=8, sticky="ew", pady=(4, 0))
        status.columnconfigure(1, weight=1)
        self.nonlocal_iv6221_progress = ttk.Progressbar(
            status, mode="determinate", maximum=1, value=0, length=110
        )
        self.nonlocal_iv6221_progress.grid(row=0, column=0, padx=(4, 8))
        status_label = ttk.Label(status, width=1)
        status_label.grid(row=0, column=1, sticky="ew")
        show_trimmed(status_label, self.nonlocal_iv6221_status_var)
        point = ttk.Label(scan, width=1)
        point.grid(row=5, column=0, columnspan=8, sticky="ew", pady=(2, 0))
        show_trimmed(point, self.nonlocal_iv6221_point_var)
        self._arrange_pair_by_width(body, params, lockins, gap=0, stack_gap=4)
        self._arrange_pair_by_width(controls, settings, scan, gap=6, stack_gap=4)
        self._keep_pair_left_room(controls, settings, scan, gap=6)

        # One X / Y / θ row per measured harmonic order, meters overlaid, as
        # on RT-E.  Only the rows of measured orders are shown.
        plots = ttk.LabelFrame(tab, text="6221-IV: X, Y, θ vs 6221 current", padding=2)
        plots.grid(row=1, column=0, sticky="nsew")
        self.nonlocal_iv6221_plot_container = plots
        for column in range(3):
            plots.columnconfigure(column, weight=1, uniform="nonlocal_iv6221")
        for order in PPMS_HARMONIC_ORDERS:
            for column, (channel, title) in enumerate((("X", "X"), ("Y", "Y"), ("theta", "θ"))):
                frame = ttk.LabelFrame(
                    plots, text=f"{PPMS_HARMONIC_LABELS[order]} {title}", padding=2
                )
                frame.grid(row=order - 1, column=column, sticky="nsew")
                canvas = self._nonlocal_plot_canvas(frame, self._redraw_nonlocal_iv6221_plots)
                canvas.configure(height=PPMS_PLOT_ROW_MIN_HEIGHT_PX)
                canvas.ppms_compact_plot = True
                self.nonlocal_iv6221_plot_frames[(order, channel)] = frame
                self.nonlocal_iv6221_canvases[(order, channel)] = canvas
        self._refresh_nonlocal_iv6221_plot_layout()

    # The rack's Zurich, as on RT-E ------------------------------------------

    def _on_nonlocal_mfli_device_changed(self) -> None:
        """The Ref. of the chosen Zurich's wiring (NONLOCAL_MFLI_DEVICE_REFERENCE_INPUTS),
        when another Zurich is chosen and none is connected."""
        device = zurich_mfli_choice(self.nonlocal_vi_mfli_device_var.get())[0]
        if device == self.__dict__.get("nonlocal_mfli_device_seen"):
            return  # the same Zurich again: a Ref. set by hand stays
        self.nonlocal_mfli_device_seen = device
        controller = self.__dict__.get("nonlocal_vi_ac_controller")
        if controller is not None and controller.mfli_connected:
            return
        reference = NONLOCAL_MFLI_DEVICE_REFERENCE_INPUTS.get(device)
        if reference and self.nonlocal_vi_mfli_reference_source_var.get() != reference:
            self.nonlocal_vi_mfli_reference_source_var.set(reference)

    def _update_nonlocal_mfli_controls(self) -> None:
        """The Zurich list while one is connected, and Ref./TC and the
        6221-IV lock-in choices while a measurement runs, are held, as on
        RT-E: a change then would not reach the instrument."""
        idle = self._nonlocal_page_idle()
        connected = self.nonlocal_vi_ac_controller.mfli_connected
        for widget, active, enabled in (
            (self.__dict__.get("nonlocal_vi_mfli_chooser"), "readonly",
             idle and not connected),
            (self.__dict__.get("nonlocal_mfli_reference_combo"), "readonly", idle),
            (self.__dict__.get("nonlocal_mfli_tc_entry"), "normal", idle),
            *((widget, active, idle) for widget, active in self.__dict__.get(
                "nonlocal_iv6221_choice_widgets", ())),
        ):
            if widget is None:
                continue
            try:
                widget.configure(state=active if enabled else "disabled")
            except (tk.TclError, AttributeError):
                pass

    def _nonlocal_mfli_settings(self) -> dict | None:
        """Ref., TC and the 6221-IV Zurich harmonic, or None if the TC is not valid."""
        try:
            tc_s = float(self.nonlocal_mfli_tc_var.get())
        except (TypeError, ValueError, tk.TclError):
            return None
        mode = str(self.nonlocal_iv6221_harmonic_vars["mfli"].get()).strip()
        # As RT-E's row: the Zurich's 6221-IV harmonic mode.
        reference = self.nonlocal_vi_mfli_reference_source_var.get().strip()
        if not (math.isfinite(tc_s) and 0 < tc_s <= 100) or mode not in PPMS_ZURICH_MODE_ORDERS \
                or reference not in NONLOCAL_MFLI_REFERENCE_INPUTS:
            return None
        return {"reference": reference, "tc_s": tc_s, "mode": mode}

    def _apply_nonlocal_mfli_config(self, settings: dict) -> None:
        """Worker: the Zurich's external reference and demodulators, as the
        RT-E Zurich row sets them (several orders: the reference on Demod 4,
        the orders on Demods 1-3, which needs MF-MD)."""
        controller = self.nonlocal_vi_ac_controller
        mode, tc_s = settings["mode"], float(settings["tc_s"])
        multi = mode in ("1+2", "1+2+3")
        if multi and not self._nonlocal_mfli_has_multi_demod():
            # Without MF-MD the rack shows the lock on the 1st harmonic; the
            # 6221-IV scan itself still asks for (and reports) the option.
            mode, multi = "1", False
        # As the PPMS/RT-E Zurich: the reference on Demod 4 (MF-MD), the
        # unused demodulators off, 10 Sa/s.
        on_demod_4 = multi or self._nonlocal_mfli_has_multi_demod()
        with controller.lock:
            readback = controller.configure_mfli(
                "AC", 1 if multi else int(mode), "R",
                reference_source=settings["reference"],
                sample_rate_hz=NONLOCAL_SAMPLE_HZ,
                input_impedance="10 MΩ", input_scaling=1.0, timeconstant_s=tc_s,
                external_reference_demodulator=3 if on_demod_4 else None,
            )
            if multi:
                rate = float(readback.get("sample_rate_hz", NONLOCAL_SAMPLE_HZ))
                controller.configure_second_harmonic(tc_s, rate=rate)
                if mode == "1+2+3":
                    controller.configure_third_harmonic(tc_s, rate=rate)
            if on_demod_4:
                controller.disable_unused_ppms_demods(mode)

    def _nonlocal_mfli_has_multi_demod(self) -> bool:
        """Whether the connected Zurich has MF-MD (several demodulators)."""
        return bool(self.nonlocal_vi_ac_controller.mfli_has_multi_demod())

    def _nonlocal_page_idle(self) -> bool:
        return (
            not self.nonlocal_vi_running
            and not self.nonlocal_vi_busy
            and self.nonlocal_keithley_task is None
            and not self.closing
            and not self.nonlocal_vi_closed
        )

    def _apply_nonlocal_mfli_settings(self, tc_edit: bool = False) -> None:
        """A Ref., TC or Zurich harmonic change, applied to a connected,
        idle Zurich at once (the scans set it up again when they start)."""
        text = self.nonlocal_mfli_tc_var.get()
        if tc_edit and text == self.nonlocal_mfli_tc_seen:
            return  # Return or leaving the field: only an edited TC is applied
        controller = self.nonlocal_vi_ac_controller
        if not controller.mfli_connected or not self._nonlocal_page_idle():
            return
        self.nonlocal_mfli_tc_seen = text
        settings = self._nonlocal_mfli_settings()
        if settings is None:
            self.nonlocal_vi_status_var.set(
                "Zurich settings not applied: TC (s) must be above 0 and at most 100"
            )
            return
        self.nonlocal_mfli_applying = True
        self.nonlocal_mfli_lock_word = "Updating"
        self.nonlocal_vi_device_connection_vars["mfli"].set("Updating")
        future = self.nonlocal_vi_executor.submit(self._apply_nonlocal_mfli_config, settings)

        def finished(completed=future, settings=settings) -> None:
            self.nonlocal_mfli_applying = False
            self.nonlocal_mfli_lock_word = None
            if self.closing or self.nonlocal_vi_closed:
                return
            error = completed.exception()
            if not self._nonlocal_page_idle():
                pass  # a measurement began meanwhile; its status stays
            elif error is None:
                self.nonlocal_vi_status_var.set(
                    f"Zurich: Ref. {settings['reference']}, TC {settings['tc_s']:g} s, "
                    f"harmonic {settings['mode']} applied"
                )
            else:
                self.nonlocal_vi_status_var.set(
                    f"Zurich settings not applied: {short_status_error(error).rstrip(';')}"
                )
            self._refresh_nonlocal_vi_connection_summary()

        future.add_done_callback(lambda _done: self.post_ui(finished))

    def _show_nonlocal_mfli_lock(self, state, range_v=None) -> None:
        """The rack Zurich row: "Locked" / "Warning" (or a short failure), as on RT-E."""
        word = "Locked" if state is True else "Warning" if state is False else state
        self.nonlocal_mfli_lock_word = word
        if self.nonlocal_vi_ac_controller.mfli_connected and not self.nonlocal_vi_busy:
            self.nonlocal_vi_device_connection_vars["mfli"].set(word or "Connected")
        if state is True or state is False:
            self._set_mfli_lock_state(state, vi=True)
        if range_v is not None:
            self.nonlocal_iv6221_zurich_range_var.set(
                "Autorange " + self._format_voltage_range(range_v)
            )

    def _poll_nonlocal_mfli(self) -> None:
        """Once a second while the page is idle, as the RT-E Zurich row:
        read the reference lock of a set-up Zurich."""
        if self.closing or self.nonlocal_vi_closed:
            return
        controller = self.nonlocal_vi_ac_controller
        if (
            controller.mfli_connected
            and controller.mfli_config
            and self._nonlocal_page_idle()
            and not self.nonlocal_mfli_poll_inflight
            and not self.nonlocal_mfli_applying
        ):
            expected = getattr(controller, "configured_frequency_hz", None)
            if not (isinstance(expected, (int, float)) and math.isfinite(expected) and expected > 0):
                try:
                    expected = float(self.nonlocal_iv6221_frequency_var.get())
                except (TypeError, ValueError, tk.TclError):
                    expected = NONLOCAL_IV6221_FREQUENCY_HZ
            self.nonlocal_mfli_poll_inflight = True

            def read(expected=expected):
                with controller.lock:
                    return controller.read_mfli(expected)

            future = self.nonlocal_vi_executor.submit(read)

            def finished(completed=future) -> None:
                self.nonlocal_mfli_poll_inflight = False
                if self.closing or self.nonlocal_vi_closed or not controller.mfli_connected:
                    return
                if not self._nonlocal_page_idle() or self.nonlocal_mfli_applying:
                    return  # a scan or a change began meanwhile; it shows its own state
                error = completed.exception()
                if error is not None:
                    self._show_nonlocal_mfli_lock("Read failed")
                    return
                sample = completed.result()
                self._show_nonlocal_mfli_lock(
                    bool(sample.get("reference_valid")), sample.get("input_range_v")
                )

            future.add_done_callback(lambda _done: self.post_ui(finished))
        self.nonlocal_mfli_after_id = self.root.after(NONLOCAL_MFLI_POLL_MS, self._poll_nonlocal_mfli)

    def _nonlocal_iv6221_order_meters(self) -> dict[int, list[str]]:
        """The meters ticked Measure that read each harmonic order."""
        meters: dict[int, list[str]] = {}
        for key in ("8", "9", "mfli"):
            if self.nonlocal_iv6221_measure_vars[key].get():
                for order in PPMS_ZURICH_MODE_ORDERS.get(
                    str(self.nonlocal_iv6221_harmonic_vars[key].get()), ()
                ):
                    meters.setdefault(order, []).append(NONLOCAL_METER_NAMES[key])
        return meters

    def _nonlocal_iv6221_measured_orders(self) -> list[int]:
        """The harmonic orders of the lock-ins ticked Measure (order 1 if none)."""
        return sorted(self._nonlocal_iv6221_order_meters()) or [1]

    def _refresh_nonlocal_iv6221_plot_layout(self) -> None:
        frames = self.__dict__.get("nonlocal_iv6221_plot_frames")
        if not frames:
            return
        meters = self._nonlocal_iv6221_order_meters()
        shown = sorted(meters) or [1]
        container = self.nonlocal_iv6221_plot_container
        for order in PPMS_HARMONIC_ORDERS:
            visible = order in shown
            container.rowconfigure(order - 1, weight=1 if visible else 0)
            for channel, title in (("X", "X"), ("Y", "Y"), ("theta", "θ")):
                frame = frames[(order, channel)]
                # The meters in the title, as on RT-E ("1st harmonic X — Zurich").
                names = ", ".join(meters.get(order, ()))
                frame.configure(
                    text=f"{PPMS_HARMONIC_LABELS[order]} {title}" + (f" — {names}" if names else "")
                )
                if visible:
                    frame.grid()
                else:
                    frame.grid_remove()
                # Every row shares the x data: only the bottom row is labelled.
                self.nonlocal_iv6221_canvases[(order, channel)].ppms_hide_x_labels = (
                    order != shown[-1]
                )
        self._redraw_nonlocal_iv6221_plots()

    def _nonlocal_plot_canvas(self, frame, redraw) -> tk.Canvas:
        frame.rowconfigure(0, weight=1)
        frame.columnconfigure(0, weight=1)
        canvas = tk.Canvas(
            frame,
            bg="#fbfcfd",
            highlightthickness=1,
            highlightbackground="#cfd6dd",
            width=self._ui_px(160, 100, canvas=True),
            height=self._ui_px(200, 120, canvas=True),
        )
        canvas.grid(row=0, column=0, sticky="nsew")
        # Also on <Map>: a <Configure> while the sub-tab is hidden is skipped
        # by the visibility check, which left a plot blank until new data.
        for sequence in ("<Configure>", "<Map>"):
            canvas.bind(sequence, lambda _event: redraw(), add="+")
        return canvas

    def _build_nonlocal_resistance_tab(self, tab) -> None:
        """|R| vs time on the pulse Keithley, as it was on MOKE-24."""
        tab.columnconfigure(0, weight=1)
        tab.rowconfigure(1, weight=1)
        controls = ttk.LabelFrame(
            tab,
            text="Continuous |R|: current source autoranged 1 nA–1 mA with 5 V protection",
            padding=7,
        )
        controls.grid(row=0, column=0, sticky="ew", pady=(0, 5))
        ttk.Checkbutton(
            controls,
            text="Resistance wiring and sample confirmed safe for the test current",
            variable=self.nonlocal_resistance_safety_var,
            command=self._update_nonlocal_keithley_controls,
        ).grid(row=0, column=0, sticky="w")
        # A negative width is a minimum: wide enough for both texts, so the
        # Stop button does not move when the text changes.
        self.nonlocal_resistance_button = ttk.Button(
            controls,
            text="Start continuous measurement",
            command=self.start_nonlocal_resistance,
            width=-27,
        )
        self.nonlocal_resistance_button.grid(row=0, column=1, padx=(12, 4))
        self.nonlocal_resistance_stop_button = ttk.Button(
            controls,
            text="Stop measurement",
            command=self.stop_nonlocal_keithley_task,
            state="disabled",
        )
        self.nonlocal_resistance_stop_button.grid(row=0, column=2)
        readouts = ttk.Frame(controls)
        readouts.grid(row=1, column=0, columnspan=3, sticky="w", pady=(6, 0))
        for variable in (
            self.nonlocal_resistance_var,
            self.nonlocal_resistance_voltage_var,
            self.nonlocal_resistance_current_var,
            self.nonlocal_resistance_source_var,
        ):
            ttk.Label(
                readouts, textvariable=variable, style="Metric.TLabel"
            ).pack(side="left", padx=(0, 16))
        frame = ttk.LabelFrame(tab, text="|R| vs time (last 20 s)", padding=6)
        frame.grid(row=1, column=0, sticky="nsew")
        self.nonlocal_resistance_canvas = self._nonlocal_plot_canvas(
            frame, self._redraw_nonlocal_resistance_plot
        )

    def _build_nonlocal_iv_tab(self, tab) -> None:
        """2400-IV as the RT-E page: the Keithley's settings in one box, the
        sweep in another (side by side when both fit), the curve below."""
        tab.columnconfigure(0, weight=1)
        tab.rowconfigure(1, weight=1)
        controls = ttk.Frame(tab)
        controls.grid(row=0, column=0, sticky="ew", pady=(0, 4))
        controls.columnconfigure(1, weight=1)
        settings = ttk.LabelFrame(controls, text="2400-IV settings", padding=6)
        settings.grid(row=0, column=0, sticky="nsew")
        scan = ttk.LabelFrame(controls, text="2400-IV scan", padding=6)
        scan.grid(row=0, column=1, sticky="nsew", padx=(6, 0))

        ttk.Checkbutton(
            settings,
            text="Wiring, current limit and voltages confirmed safe",
            variable=self.nonlocal_iv_safety_var,
            command=self._update_nonlocal_keithley_controls,
        ).grid(row=0, column=0, columnspan=4, sticky="w")
        # No Sample box (user, 2026-10-09).
        ttk.Label(settings, text="Current limit A:").grid(row=1, column=0, sticky="e", pady=2)
        ttk.Entry(settings, textvariable=self.nonlocal_iv_limit_var, width=9).grid(
            row=1, column=1, sticky="w", padx=(3, 0), pady=2
        )
        # The Keithley on its own (user, 2026-10-09): a voltage left on until
        # OFF, and one pulse; both with the Current limit A and the safety
        # tick, the 6221 switched off first.
        manual = ttk.Frame(settings)
        manual.grid(row=2, column=0, columnspan=4, sticky="w", pady=(4, 0))
        self.nonlocal_iv_set_label = ttk.Label(manual, text=f"{NONLOCAL_DEFAULT_KEITHLEY_MODEL} V:")
        self.nonlocal_iv_set_label.grid(row=0, column=0, sticky="e", pady=2)
        ttk.Entry(manual, textvariable=self.nonlocal_iv_set_voltage_var, width=8).grid(
            row=0, column=1, sticky="w", padx=(3, 6), pady=2
        )
        self.nonlocal_iv_set_button = ttk.Button(
            manual, text=f"Set {NONLOCAL_DEFAULT_KEITHLEY_MODEL}", width=10,
            command=self.set_nonlocal_keithley_voltage,
        )
        self.nonlocal_iv_set_button.grid(row=0, column=2, columnspan=2, sticky="w", pady=2)
        self.nonlocal_iv_off_button = ttk.Button(
            manual, text=f"{NONLOCAL_DEFAULT_KEITHLEY_MODEL} / 6221 OFF", width=15,
            command=self.stop_nonlocal_vi,
        )
        self.nonlocal_iv_off_button.grid(row=0, column=4, sticky="w", padx=(6, 0), pady=2)
        ttk.Label(manual, text="Pulse V:").grid(row=1, column=0, sticky="e", pady=2)
        ttk.Entry(manual, textvariable=self.nonlocal_iv_pulse_voltage_var, width=8).grid(
            row=1, column=1, sticky="w", padx=(3, 6), pady=2
        )
        ttk.Label(manual, text="Width s:").grid(row=1, column=2, sticky="e", pady=2)
        ttk.Entry(manual, textvariable=self.nonlocal_iv_pulse_width_var, width=6).grid(
            row=1, column=3, sticky="w", padx=(3, 0), pady=2
        )
        self.nonlocal_iv_pulse_button = ttk.Button(
            manual, text="Apply pulse", width=15, command=self.apply_nonlocal_keithley_pulse,
        )
        self.nonlocal_iv_pulse_button.grid(row=1, column=4, sticky="w", padx=(6, 0), pady=2)
        ttk.Label(manual, textvariable=self.nonlocal_iv_keithley_var).grid(
            row=2, column=0, columnspan=5, sticky="w", pady=(2, 0)
        )
        ttk.Label(
            settings,
            text=(
                f"Voltage source: up to ±{NONLOCAL_KEITHLEY_MAX_ABS_V['2400']:g} V on a 2400, "
                f"±{NONLOCAL_KEITHLEY_MAX_ABS_V['2410']:g} V on a 2410 (above ±"
                f"{KEITHLEY_LOW_SOURCE_RANGE_V:g} V on the high range);\nhardware OVP at the "
                f"lowest level above the sweep; current read at NPLC {NONLOCAL_IV_SWEEP_NPLC:g}"
            ),
            style="Muted.TLabel",
        ).grid(row=3, column=0, columnspan=4, sticky="w", pady=(4, 0))

        for index, (label, variable) in enumerate((
            ("Start V", self.nonlocal_iv_start_var),
            ("End V", self.nonlocal_iv_end_var),
            ("Step V", self.nonlocal_iv_step_var),
            ("Settle s", self.nonlocal_iv_settle_var),
        )):
            ttk.Label(scan, text=f"{label}:").grid(
                row=0, column=2 * index, sticky="e", padx=(0 if index == 0 else 10, 3), pady=2
            )
            ttk.Entry(scan, textvariable=variable, width=7).grid(
                row=0, column=2 * index + 1, sticky="w", pady=2
            )
        buttons = ttk.Frame(scan)
        buttons.grid(row=1, column=0, columnspan=8, sticky="w", pady=(6, 0))
        self.nonlocal_iv_start_button = ttk.Button(
            buttons, text="Choose folder and start 2400-IV sweep",
            command=self.start_nonlocal_iv_sweep,
        )
        self.nonlocal_iv_start_button.pack(side="left", padx=(0, 4))
        self.nonlocal_iv_stop_button = ttk.Button(
            buttons, text="Stop sweep", command=self.stop_nonlocal_keithley_task, state="disabled",
        )
        self.nonlocal_iv_stop_button.pack(side="left", padx=(0, 4))
        # The CSV is written point by point; the plot can be added beside it.
        self.nonlocal_iv_save_button = ttk.Button(
            buttons, text="Save plot PNG", command=self.save_nonlocal_iv_png, state="disabled",
        )
        self.nonlocal_iv_save_button.pack(side="left")
        progress = ttk.Frame(scan)
        progress.grid(row=2, column=0, columnspan=8, sticky="ew", pady=(6, 0))
        progress.columnconfigure(0, weight=1)
        self.nonlocal_iv_progress = ttk.Progressbar(
            progress, mode="determinate", maximum=1, value=0, length=120
        )
        self.nonlocal_iv_progress.grid(row=0, column=0, sticky="ew", padx=(0, 8))
        ttk.Label(
            progress, textvariable=self.nonlocal_iv_eta_var, style="Success.TLabel", width=20,
        ).grid(row=0, column=1, sticky="w")
        point = ttk.Label(scan, style="Metric.TLabel", anchor="w", width=1)
        point.grid(row=3, column=0, columnspan=8, sticky="ew", pady=(4, 0))
        show_trimmed(point, self.nonlocal_iv_point_var)
        self._arrange_pair_by_width(controls, settings, scan, gap=6, stack_gap=4)

        frame = ttk.LabelFrame(tab, text="Current vs voltage", padding=6)
        frame.grid(row=1, column=0, sticky="nsew")
        self.nonlocal_iv_canvas = self._nonlocal_plot_canvas(
            frame, self._redraw_nonlocal_iv_plot
        )

    def _populate_roi_nudge_toolbar(
        self,
        parent: ttk.Frame,
        command: Callable[[str], None],
        button_store: list[tk.Widget],
        *,
        initial_state: str = "normal",
    ) -> None:
        """Build the same compact A/W/H/X/Y minus-plus toolbar on every tab."""
        groups = (
            ("A", "rotate_left", "rotate_right"),
            ("W", "width_minus", "width_plus"),
            ("H", "height_minus", "height_plus"),
            ("X", "move_left", "move_right"),
            ("Y", "move_up", "move_down"),
        )
        for index, (axis, minus_action, plus_action) in enumerate(groups):
            group = ttk.Frame(parent)
            group.pack(side="left", padx=(0 if index == 0 else 5, 0))
            ttk.Label(group, text=axis, style="Muted.TLabel").pack(side="left")
            for symbol, action in (("−", minus_action), ("+", plus_action)):
                button = ttk.Button(
                    group,
                    text=symbol,
                    width=2,
                    style="Compact.TButton",
                    state=initial_state,
                    command=lambda selected=action: command(selected),
                )
                button.pack(side="left", padx=(2, 0))
                button_store.append(button)

    def build_channel(self, parent, channel: int, row: int, column: int) -> None:
        panel = ttk.LabelFrame(parent, text=f"LED channel {channel}", padding=7)
        # No side padding: the panels share the page's left edge.
        panel.grid(row=row, column=column, sticky="nsew", padx=0, pady=3)
        panel.columnconfigure(0, weight=1)
        variables: dict[str, tk.Variable] = {
            "i": tk.IntVar(value=0),
            "m": tk.StringVar(value="Off"),
            "p": tk.IntVar(value=5),
            "g": tk.IntVar(value=0),
            "d": tk.IntVar(value=5),
            "f": tk.IntVar(value=0),
        }
        self.channel_vars[channel] = variables

        primary = ttk.Frame(panel)
        primary.grid(row=0, column=0, sticky="ew")
        primary.columnconfigure(5, weight=1)
        ttk.Label(primary, text="Current:").grid(row=0, column=0)
        ttk.Spinbox(
            primary,
            from_=0,
            to=CURRENT_LIMIT,
            textvariable=variables["i"],
            width=9,
        ).grid(row=0, column=1, padx=(0, 10))
        ttk.Label(primary, text="Mode:").grid(row=0, column=2)
        ttk.Combobox(
            primary,
            textvariable=variables["m"],
            values=tuple(MODE_LABEL_TO_VALUE),
            state="readonly",
            width=7,
        ).grid(row=0, column=3, padx=(0, 10))

        actions = ttk.Frame(primary)
        actions.grid(row=0, column=5, sticky="e")
        # Eight characters, as on the stage buttons, instead of the theme's
        # eleven-character minimum: it keeps the channel column narrow enough
        # for the ROI graph and its title in the default window.
        apply_button = ttk.Button(
            actions,
            text="Apply",
            style="Accent.TButton",
            width=8,
            command=lambda selected=channel: self.apply_channel(selected),
        )
        apply_button.pack(side="left", padx=(0, 3))
        self.action_widgets.append(apply_button)
        query_button = ttk.Button(
            actions,
            text="Query",
            width=8,
            command=lambda selected=channel: self.query_channel(selected),
        )
        query_button.pack(side="left")
        self.action_widgets.append(query_button)

        advanced = ttk.Frame(panel)
        advanced.grid(row=1, column=0, sticky="w", pady=(7, 0))
        self.raw_parameter_frames.append(advanced)
        ttk.Label(advanced, text="Advanced:", style="Muted.TLabel").grid(
            row=0, column=0, padx=(0, 2)
        )
        for index, parameter in enumerate(("p", "g", "d", "f")):
            ttk.Label(advanced, text=f"{parameter}=").grid(
                row=0, column=1 + index * 2
            )
            entry = ttk.Entry(advanced, textvariable=variables[parameter], width=6)
            entry.grid(row=0, column=2 + index * 2, padx=(0, 7))
            self.raw_entries.append(entry)
        advanced.grid_remove()

    def toggle_led_log(self) -> None:
        visible = not bool(self.led_log_visible_var.get())
        self.led_log_visible_var.set(visible)
        # The log sits in row 6 (row 5 is the rotation stage).  Shown, it
        # takes the spare height; hidden, the blank row 7 takes it again.
        if visible:
            self.led_log_frame.grid()
            self.led_outer.rowconfigure(6, weight=1)
            self.led_outer.rowconfigure(7, weight=0)
            self.led_log_toggle_button.configure(text="Hide log")
        else:
            self.led_log_frame.grid_remove()
            self.led_outer.rowconfigure(6, weight=0)
            self.led_outer.rowconfigure(7, weight=1)
            self.led_log_toggle_button.configure(text="Show log")

    def show_motor_window(self) -> None:
        if self.motor_app is None:
            messagebox.showinfo("Motor control", "The motor subsystem is still initialising; please wait.")
            return
        self.notebook.select(self.motor_tab)

    def attach_motor(self, motor_app_class) -> None:
        self.motor_app_class = motor_app_class
        self.motor_app = motor_app_class(self.motor_tab, embedded=True)

    def _set_camera_dependent_controls(self, enabled: bool) -> None:
        state = "normal" if enabled else "disabled"
        for button in self.difference_mode_buttons:
            button.configure(state=state)
        for button in self.difference_clim_buttons:
            button.configure(state=state)
        for button in (*self.difference_capture_buttons, *self.objective_100x_marker_buttons):
            button.configure(state=state)
        for button in self.camera_video_buttons:
            button.configure(state=state)

    def _update_camera_launcher_controls(self) -> None:
        has_window = self.camera_window is not None
        if self.camera_connect_button is not None:
            self.camera_connect_button.configure(
                state="disabled" if has_window else "normal"
            )
        if self.camera_disconnect_button is not None:
            self.camera_disconnect_button.configure(
                state="normal" if has_window else "disabled"
            )
        if self.camera_show_button is not None:
            self.camera_show_button.configure(
                state=(
                    "normal"
                    if self.camera_connected and not self.camera_window_visible
                    else "disabled"
                )
            )
        if self.camera_hide_button is not None:
            self.camera_hide_button.configure(
                state=(
                    "normal"
                    if self.camera_connected and self.camera_window_visible
                    else "disabled"
                )
            )

    def connect_camera(self) -> None:
        """Create the PCO worker only after an explicit operator request."""
        if self.camera_window is not None:
            return
        self.camera_connected = False
        self.camera_window_visible = False
        self.camera_window_status_var.set("Connecting to the PCO camera and waiting for the first frame…")
        if self.camera_connect_button is not None:
            self.camera_connect_button.configure(state="disabled")
        try:
            camera = TkCameraWindow(self.root, self)
        except BaseException as error:
            self.camera_start_failed(error)
            messagebox.showerror("Camera connection failed", str(error), parent=self.root)
            return
        self.attach_camera(camera)

    def attach_camera(self, camera_window) -> None:
        self.camera_window = camera_window
        self.camera_connected = False
        self.camera_window_visible = False
        self._set_connection_indicator("camera", False)
        self.camera_window_status_var.set("Connecting to the PCO camera and waiting for the first frame…")
        self._set_camera_dependent_controls(False)
        self._update_camera_launcher_controls()
        self._update_moke_roi_controls()

    def camera_connection_ready(self) -> None:
        if self.camera_window is None:
            return
        self.camera_connected = True
        self._set_connection_indicator("camera", True)
        self._set_camera_dependent_controls(True)
        self.difference_status_var.set("Difference mode: off")
        self.camera_window_visibility_changed(self.camera_window_visible)

    def camera_start_failed(self, error: BaseException) -> None:
        # A running MOKE scan has no images any more: stop it (review,
        # 2026-10-09; it went on driving the magnet or Keithley).
        for running, event in (
            (self.magnet_scan_running, self.magnet_scan_stop_event),
            (self.keithley_scan_running, self.keithley_stop_event),
            (self.k6221_scan_running, self.k6221_stop_event),
        ):
            if running:
                event.set()
        failed_camera = self.camera_window
        self.camera_window = None
        self.camera_connected = False
        self.camera_window_visible = False
        self._set_connection_indicator("camera", False)
        if failed_camera is not None:
            try:
                failed_camera.close()
            except BaseException:
                pass
        self.camera_window_status_var.set(
            f"Camera start failed: {short_status_error(error, 100)}"
        )
        self._set_camera_dependent_controls(False)
        self._update_camera_launcher_controls()

    def camera_window_visibility_changed(self, visible: bool) -> None:
        if self.camera_window is None:
            self.camera_window_visible = False
            self.camera_window_status_var.set("Camera not connected")
            self._update_camera_launcher_controls()
            return
        self.camera_window_visible = bool(visible)
        self.camera_window_status_var.set(
            "Camera acquiring · Camera Live window shown"
            if self.camera_connected and visible
            else "Camera acquiring · Camera Live window hidden"
            if self.camera_connected
            else "Connecting to the PCO camera and waiting for the first frame…"
        )
        self._update_camera_launcher_controls()

    def show_camera_live_window(self) -> None:
        camera = self.camera_window
        if camera is None or not self.camera_connected:
            messagebox.showwarning(
                "Camera Live", "Connect the camera and wait for the first frame first.", parent=self.root
            )
            return
        try:
            camera.show()
        except BaseException as error:
            self.camera_start_failed(error)
            messagebox.showerror("Camera Live", str(error), parent=self.root)

    def hide_camera_live_window(self) -> None:
        camera = self.camera_window
        if camera is not None:
            camera.hide()

    def disconnect_camera(self) -> None:
        camera = self.camera_window
        if camera is None:
            return
        if (
            self.magnet_scan_running
            or self.keithley_scan_running
            or self.k6221_scan_running
        ):
            messagebox.showwarning(
                "Disconnect camera",
                "A field, voltage or pulse scan is running; the camera cannot be disconnected.",
                parent=self.root,
            )
            return
        if camera.video_recorder is not None or self.camera_video_stopping:
            messagebox.showwarning(
                "Disconnect camera",
                "Stop and save the Camera Live recording first.",
                parent=self.root,
            )
            return
        self.camera_window_status_var.set("Stopping acquisition and disconnecting the camera…")
        self.camera_window = None
        try:
            camera.close()
        except BaseException as error:
            self.append_log(f"Camera disconnect warning: {error}")
            messagebox.showerror("Disconnect camera", str(error), parent=self.root)
        self.camera_connected = False
        self.camera_window_visible = False
        self._set_connection_indicator("camera", False)
        self._set_camera_dependent_controls(False)
        self.clear_camera_roi()
        self.difference_status_var.set("Camera not connected")
        self.camera_window_status_var.set("Camera not connected")
        self._update_camera_launcher_controls()

    def _on_notebook_tab_changed(self, _event=None) -> None:
        """Redraw only the page that just became visible."""
        if self.closing:
            return
        try:
            self.root.after_idle(self._redraw_active_tab)
        except tk.TclError:
            pass

    def _redraw_active_tab(self) -> None:
        if self.closing or self.notebook is None:
            return
        try:
            selected = self.notebook.nametowidget(self.notebook.select())
        except (KeyError, tk.TclError):
            return
        self._redraw_live_intensity_plots()
        if selected is self.difference_tab:
            self._redraw_moke_plot()
        elif selected is self.keithley_tab:
            self._redraw_keithley_plot()
        elif selected is self.nonlocal_vi_tab:
            self._redraw_nonlocal_vi_plots()
            self._redraw_nonlocal_resistance_plot()
            self._redraw_nonlocal_iv_plot()
            self._redraw_nonlocal_iv6221_plots()

    @contextmanager
    def camera_render_paused(self, reason: str):
        """Suspend only Camera Live rendering during file-oriented UI work."""
        camera = self.pause_camera_rendering(reason)
        try:
            yield
        finally:
            self.resume_camera_rendering(camera)

    def pause_camera_rendering(self, reason: str):
        camera = self.camera_window
        if camera is not None:
            camera.pause_rendering(reason)
        return camera

    @staticmethod
    def resume_camera_rendering(camera) -> None:
        if camera is not None:
            camera.resume_rendering()

    @staticmethod
    def write_csv_exports(exports) -> None:
        """Write one or more immutable CSV snapshots on the file worker."""
        for path, header, rows in exports:
            destination = Path(path)
            destination.parent.mkdir(parents=True, exist_ok=True)
            with destination.open("x", newline="", encoding="utf-8-sig") as file:
                writer = csv.writer(file)
                writer.writerow(header)
                writer.writerows(rows)

    @staticmethod
    def write_parameter_log(path: Path, text: str) -> None:
        """Write one immutable UTF-8 experiment-parameter log."""
        destination = Path(path)
        destination.parent.mkdir(parents=True, exist_ok=True)
        with destination.open("x", encoding="utf-8", newline="\n") as file:
            file.write(text)

    @staticmethod
    def format_parameter_log(title: str, parameters: dict[str, object]) -> str:
        """Render a stable, human-readable key=value scan log."""
        lines = [
            title,
            f"log_saved_local={datetime_module.datetime.now().isoformat(timespec='seconds')}",
        ]
        for key, value in parameters.items():
            if isinstance(value, bool):
                rendered = "true" if value else "false"
            elif value is None:
                rendered = "none"
            elif isinstance(value, float):
                rendered = f"{value:.12g}"
            else:
                rendered = str(value)
            lines.append(f"{key}={rendered}")
        return "\n".join(lines) + "\n"

    def camera_scan_parameter_snapshot(self, roi) -> dict[str, object]:
        """Capture camera/ROI processing settings used by a scan."""
        camera = self.camera_window
        frame = None if camera is None else camera.latest_frame
        parameters: dict[str, object] = {}
        if roi is not None:
            for key in ("cx", "cy", "w", "h", "angle"):
                parameters[f"roi.{key}"] = float(roi[key])
        if frame is None:
            parameters["camera.frame_available"] = False
            return parameters
        raw = np.asarray(frame.raw)
        parameters.update(
            {
                "camera.frame_available": True,
                "camera.raw_dtype": str(raw.dtype),
                "camera.raw_width_px": int(raw.shape[1]) if raw.ndim == 2 else -1,
                "camera.raw_height_px": int(raw.shape[0]) if raw.ndim == 2 else -1,
                "camera.exposure_ms": float(frame.exposure_ms),
                "camera.background_enabled": bool(frame.background_enabled),
                "camera.background_mode": str(frame.background_mode),
                "camera.temporal_average_frames": int(
                    frame.temporal_average_count
                ),
                "camera.spatial_binning": int(frame.spatial_binning),
                "camera.mean_filter_size": int(frame.mean_filter_size),
                "camera.display_contrast_auto": bool(frame.contrast_auto),
            }
        )
        try:
            contrast_mode, active_clim = camera.worker.difference_contrast_state()
        except BaseException:
            contrast_mode, active_clim = "unknown", None
        parameters["camera.difference_clim_mode"] = contrast_mode
        parameters["camera.difference_clim"] = (
            "none"
            if active_clim is None
            else f"{float(active_clim[0]):.12g},{float(active_clim[1]):.12g}"
        )
        return parameters

    @staticmethod
    def _snapshot_variable(variable, fallback: object = "unavailable") -> object:
        """Read a Tk variable for a log snapshot without raising on shutdown."""
        try:
            return variable.get()
        except (AttributeError, RuntimeError, tk.TclError):
            return fallback

    def moke_hardware_parameter_snapshot(
        self, phase: str
    ) -> dict[str, object]:
        """Capture cached illumination and magnet state without hardware I/O.

        MOKE export must remain responsive even when a serial adapter is slow.
        The snapshot therefore records GUI setpoints, the latest verified
        readbacks already cached by the instrument workers, and connection /
        arming metadata.  It deliberately does not issue fresh serial queries.
        ``phase`` distinguishes the state at scan start from the state when the
        data are exported.
        """
        phase = str(phase).strip().lower().replace(" ", "_") or "snapshot"
        root = f"hardware.{phase}"
        parameters: dict[str, object] = {
            f"{root}.captured_local": datetime_module.datetime.now().isoformat(
                timespec="seconds"
            ),
            # Illumination controller and serial-link state.
            f"{root}.illumination.connection_summary": self._snapshot_variable(
                self.connection_var
            ),
            f"{root}.illumination.operation_status": self._snapshot_variable(
                self.operation_var
            ),
            f"{root}.illumination.connected": bool(self.controller.is_connected),
            f"{root}.illumination.configured_port": self._snapshot_variable(
                self.port_var
            ),
            f"{root}.illumination.connected_port": self.controller.port,
            f"{root}.illumination.protocol_baud": int(BAUD_RATE),
            f"{root}.illumination.protocol_format": "8-N-1",
            f"{root}.illumination.read_timeout_s": float(READ_TIMEOUT_S),
            f"{root}.illumination.write_timeout_s": float(WRITE_TIMEOUT_S),
            f"{root}.illumination.command_delay_s": float(COMMAND_DELAY_S),
            f"{root}.illumination.current_limit": int(CURRENT_LIMIT),
            f"{root}.illumination.global_continuous_current": self._snapshot_variable(
                self.global_current_var
            ),
            f"{root}.illumination.auto_readback": bool(
                self._snapshot_variable(self.auto_readback_var, False)
            ),
            f"{root}.illumination.advanced_parameter_edit_visible": bool(
                self._snapshot_variable(self.raw_edit_var, False)
            ),
            # Magnet connection, selector, polling and protocol state.
            f"{root}.magnet.connection_summary": self._snapshot_variable(
                self.magnet_connection_var
            ),
            f"{root}.magnet.operation_status": self._snapshot_variable(
                self.magnet_status_var
            ),
            f"{root}.magnet.all_devices_connected": bool(
                self._magnet_devices_ready()
            ),
            f"{root}.magnet.physical_selector_gui": self._snapshot_variable(
                self.magnet_switch_var
            ),
            f"{root}.magnet.physical_selector_confirmed": str(
                self.magnet_switch_confirmed_label
            ),
            f"{root}.magnet.selected_channel_key": (
                self._selected_magnet_switch_key() or "none"
            ),
            f"{root}.magnet.safety_confirmed": bool(
                self._snapshot_variable(self.magnet_safety_var, False)
            ),
            f"{root}.magnet.auto_poll_enabled": bool(
                self._snapshot_variable(self.magnet_auto_poll_var, False)
            ),
            f"{root}.magnet.poll_interval_s": self._snapshot_variable(
                self.magnet_poll_interval_var
            ),
            f"{root}.magnet.poll_inflight": bool(self.magnet_poll_inflight),
            f"{root}.magnet.poll_consecutive_failures": int(
                self.magnet_poll_failures
            ),
            f"{root}.magnet.command_busy": bool(self.magnet_busy),
            f"{root}.magnet.scan_running": bool(self.magnet_scan_running),
            f"{root}.magnet.scan_active_channel_key": (
                self.magnet_scan_active_key or "none"
            ),
            f"{root}.magnet.current_limit_A": float(MAGNET_CURRENT_LIMIT_A),
            f"{root}.magnet.current_readback_abs_tolerance_A": float(
                MAGNET_CURRENT_READBACK_TOLERANCE_A
            ),
            f"{root}.magnet.current_readback_relative_tolerance": float(
                MAGNET_CURRENT_READBACK_REL_TOLERANCE
            ),
            f"{root}.magnet.protocol_baud": int(MAGNET_BAUD_RATE),
            f"{root}.magnet.protocol_format": "8-N-1",
            f"{root}.magnet.reply_deadline_s": float(MAGNET_REPLY_DEADLINE_S),
            f"{root}.magnet.query_attempts": int(MAGNET_QUERY_ATTEMPTS),
        }

        for channel in CHANNELS:
            variables = self.channel_vars.get(channel, {})
            channel_root = f"{root}.illumination.channel_{channel}"
            mode_label = self._snapshot_variable(
                variables.get("m"), "unavailable"
            )
            parameters.update(
                {
                    f"{channel_root}.gui_current": self._snapshot_variable(
                        variables.get("i")
                    ),
                    f"{channel_root}.gui_mode_label": mode_label,
                    f"{channel_root}.gui_mode_code": MODE_LABEL_TO_VALUE.get(
                        str(mode_label), "unavailable"
                    ),
                    f"{channel_root}.gui_p": self._snapshot_variable(
                        variables.get("p")
                    ),
                    f"{channel_root}.gui_g": self._snapshot_variable(
                        variables.get("g")
                    ),
                    f"{channel_root}.gui_d": self._snapshot_variable(
                        variables.get("d")
                    ),
                    f"{channel_root}.gui_f": self._snapshot_variable(
                        variables.get("f")
                    ),
                }
            )

        for key in ("OUT", "IN"):
            label = MAGNET_CHANNEL_LABELS[key]
            channel = self.magnet_channels[key]
            bop = channel.bop
            gauss = channel.gauss
            channel_root = f"{root}.magnet.{key}"
            parameters.update(
                {
                    f"{channel_root}.label": label,
                    f"{channel_root}.configured_BOP_port": self._snapshot_variable(
                        self.magnet_port_vars[f"{key}_BOP"]
                    ),
                    f"{channel_root}.configured_Gauss_port": self._snapshot_variable(
                        self.magnet_port_vars[f"{key}_GAUSS"]
                    ),
                    f"{channel_root}.BOP_connected": bool(
                        bop is not None and bop.connected
                    ),
                    f"{channel_root}.Gauss_connected": bool(
                        gauss is not None and gauss.connected
                    ),
                    f"{channel_root}.BOP_connected_port": (
                        None if bop is None else bop.port
                    ),
                    f"{channel_root}.Gauss_connected_port": (
                        None if gauss is None else gauss.port
                    ),
                    f"{channel_root}.BOP_output_armed": bool(
                        bop is not None and bop.output_armed
                    ),
                    f"{channel_root}.gui_target_current_A": self._snapshot_variable(
                        self.magnet_target_vars[key]
                    ),
                    f"{channel_root}.manual_step_A": self._snapshot_variable(
                        self.magnet_manual_step_vars[key]
                    ),
                    f"{channel_root}.cached_verified_current_A": self.magnet_last_currents[
                        key
                    ],
                    f"{channel_root}.gui_current_readback": self._snapshot_variable(
                        self.magnet_current_vars[key]
                    ),
                    f"{channel_root}.gui_field_readback": self._snapshot_variable(
                        self.magnet_field_vars[key]
                    ),
                    f"{channel_root}.is_selected_physical_path": bool(
                        self._selected_magnet_switch_key() == key
                    ),
                }
            )
        return parameters

    def _refresh_file_export_controls(self) -> None:
        """Keep save buttons consistent with background export ownership."""
        for method_name in (
            "_update_magnet_scan_controls",
            "_update_keithley_controls",
            "_update_k6221_controls",
            "_update_nonlocal_keithley_controls",
        ):
            method = getattr(self, method_name, None)
            if method is not None:
                method()

    def submit_file_export(
        self,
        key: str,
        camera,
        work: Callable[[], object],
        on_success: Callable[[object], None],
        on_error: Callable[[BaseException], None],
    ) -> None:
        """Run disk I/O away from Tk and every instrument command queue."""
        self.active_file_exports.add(key)
        self._refresh_file_export_controls()
        try:
            future = self.file_executor.submit(work)
        except BaseException as error:
            self.active_file_exports.discard(key)
            self._refresh_file_export_controls()
            self.resume_camera_rendering(camera)
            on_error(error)
            return

        def completed() -> None:
            try:
                if self.closing:
                    return
                try:
                    result = future.result()
                except BaseException as error:
                    on_error(error)
                else:
                    on_success(result)
            finally:
                self.active_file_exports.discard(key)
                if not self.closing:
                    self._refresh_file_export_controls()
                self.resume_camera_rendering(camera)

        future.add_done_callback(lambda _future: self.post_ui(completed))

    def latest_raw_image_snapshot(self):
        camera = self.camera_window
        frame = None if camera is None else camera.latest_frame
        if frame is None or frame.raw is None:
            raise RuntimeError("The camera has not produced a raw frame to save yet")
        array = np.asarray(frame.raw)
        if array.dtype != np.uint16 or array.ndim != 2:
            raise RuntimeError(
                f"Unexpected camera raw frame format: dtype={array.dtype}, shape={array.shape}"
            )
        return array.copy()

    def latest_display_image_snapshot(self):
        """Return the marker-free 8-bit Camera Live viewport as displayed."""
        camera = self.camera_window
        array = None if camera is None else camera.latest_display_image
        geometry = None if camera is None else camera.latest_display_geometry
        return self._compose_display_snapshot(array, geometry)

    @staticmethod
    def _compose_display_snapshot(array, geometry):
        """The displayed 8-bit image on its canvas-sized black background."""
        if array is None or geometry is None:
            raise RuntimeError("Camera Live has not produced a display image to save yet")
        array = np.asarray(array)
        if array.dtype != np.uint8 or array.ndim != 2:
            raise RuntimeError(
                f"Unexpected display image format: dtype={array.dtype}, shape={array.shape}"
            )
        offset_x, offset_y, canvas_width, canvas_height = geometry
        snapshot = np.zeros((canvas_height, canvas_width), dtype=np.uint8)
        paste_height = min(array.shape[0], canvas_height - offset_y)
        paste_width = min(array.shape[1], canvas_width - offset_x)
        if paste_height <= 0 or paste_width <= 0:
            raise RuntimeError("The display image canvas size is invalid")
        snapshot[
            offset_y : offset_y + paste_height,
            offset_x : offset_x + paste_width,
        ] = array[:paste_height, :paste_width]
        return snapshot

    def latest_processed_image_snapshot(self):
        """Return the exact signed difference image used by ROI measurement."""
        camera = self.camera_window
        frame = None if camera is None else camera.latest_frame
        if frame is None or frame.display_difference is None:
            raise RuntimeError("Enable plain or drift-tracking difference first and wait for one processed frame")
        array = np.asarray(frame.display_difference, dtype=np.float32)
        if array.ndim != 2 or not np.all(np.isfinite(array)):
            raise RuntimeError(
                f"Unexpected processed image format: dtype={array.dtype}, shape={array.shape}"
            )
        settings = {
            "mode": frame.background_mode,
            "temporal_count": frame.temporal_average_count,
            "spatial_binning": frame.spatial_binning,
            "mean_filter_size": frame.mean_filter_size,
        }
        return array.copy(), settings

    @staticmethod
    def processed_image_settings_suffix(settings) -> str:
        mode = "TrackingDiff" if settings["mode"] == "tracking" else "PlainDiff"
        return (
            f"{mode}_Avg{int(settings['temporal_count'])}_"
            f"Bin{int(settings['spatial_binning'])}x"
            f"{int(settings['spatial_binning'])}_"
            f"Mean{int(settings['mean_filter_size'])}x"
            f"{int(settings['mean_filter_size'])}"
        )

    def save_current_display_image(self, source: str) -> None:
        """Save the current zoom/contrast-mapped viewport without overlays."""
        export_key = f"display-image:{source}"
        if export_key in self.active_file_exports:
            self.operation_var.set(f"{source} display image is still being saved; please wait")
            return
        camera = self.pause_camera_rendering(f"Saving {source} display image")
        try:
            snapshot = self.latest_display_image_snapshot()
        except BaseException as error:
            self.resume_camera_rendering(camera)
            messagebox.showwarning("Save display image", str(error), parent=self.root)
            return
        timestamp = datetime_module.datetime.now().strftime("%Y%m%d_%H%M%S_%f")
        selected = filedialog.asksaveasfilename(
            parent=self.root,
            title=f"Save {source} current Camera Live display image (no overlays)",
            defaultextension=".png",
            initialfile=f"{source}_CameraLive_display8_{timestamp}.png",
            filetypes=(("PNG image", "*.png"), ("All files", "*.*")),
        )
        if not selected:
            self.resume_camera_rendering(camera)
            return
        destination = Path(selected)
        self.operation_var.set(f"Saving {source} display image in the background…")

        def work():
            save_display_u8_png(snapshot, destination)
            return destination

        def failed(error: BaseException) -> None:
            self.operation_var.set(f"{source} display image save failed")
            messagebox.showerror(
                "Save display image failed", str(error), parent=self.root
            )

        def saved(path: Path) -> None:
            self.operation_var.set(f"{source} display image saved")
            messagebox.showinfo(
                "Save display image",
                "Saved the current Camera Live 8-bit display image (no overlays):\n"
                f"{path}",
                parent=self.root,
            )

        self.submit_file_export(export_key, camera, work, saved, failed)

